/** Pigułka z płynnym metalem — odwzorowanie oryginalnego `liquid-metal-button`.
 *
 *  Sedno tamtego projektu: shader NIE wypełnia przycisku. Leży pod spodem, a na
 *  wierzchu siedzi ciemna pigułka mniejsza o 2 px z każdej strony, więc metal widać
 *  wyłącznie jako cienką, ruchomą obwódkę. Wnętrze zostaje prawie czarne
 *  (gradient #202020 → #000), napis jest wyciszony, a całość niesie miękki cień.
 *
 *  Warstwy, od spodu (w oryginale rozsunięte w 3D przez translateZ):
 *    1. metal  — shader na całej powierzchni
 *    2. licowa pigułka — ciemny gradient, przy wciśnięciu dostaje cień do wewnątrz
 *    3. napis + fala rozchodząca się od punktu dotknięcia
 */
import * as Haptics from "expo-haptics";
import { LinearGradient } from "expo-linear-gradient";
import React, { useRef, useState } from "react";
import {
  Animated, Easing, Platform, Pressable, StyleSheet, Text, TextStyle, View, ViewStyle,
} from "react-native";
import { C } from "../theme";
import LiquidSurface, { LiquidHandle } from "./LiquidSurface";

export const PILL_SIZES = {
  sm: { padV: 7, padH: 14, font: 12.5, rim: 1.5 },
  md: { padV: 11, padH: 18, font: 13.5, rim: 2 },
  lg: { padV: 15, padH: 24, font: 15.5, rim: 2 },
};

type Props = {
  label?: string;
  children?: React.ReactNode;
  onPress?: () => void;
  size?: keyof typeof PILL_SIZES;
  /** barwa obwódki — domyślnie srebro; kolor tylko muska metal */
  tint?: string;
  tintMix?: number;
  /** wybrany stan rozjaśnia napis; metal płynie zawsze */
  active?: boolean;
  disabled?: boolean;
  full?: boolean;
  fps?: number;
  style?: ViewStyle;
  textStyle?: TextStyle;
};

export default function LiquidPill({
  label, children, onPress, size = "md", tint = "#9fb2d0", tintMix = 0.2,
  active = false, disabled = false, full = false, fps = 30, style, textStyle,
}: Props) {
  const d = PILL_SIZES[size];
  const scale = useRef(new Animated.Value(1)).current;
  const shift = useRef(new Animated.Value(0)).current;
  const wave = useRef(new Animated.Value(0)).current;
  const boost = useRef<LiquidHandle | null>(null);
  const [spot, setSpot] = useState({ x: 0, y: 0 });
  const [pressed, setPressed] = useState(false);

  function down(e: any) {
    if (disabled) return;
    if (Platform.OS !== "web") Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
    boost.current?.boost();
    setPressed(true);
    const { locationX = 0, locationY = 0 } = e?.nativeEvent || {};
    setSpot({ x: locationX, y: locationY });
    wave.setValue(0);
    Animated.timing(wave, {
      toValue: 1, duration: 600, easing: Easing.out(Easing.quad), useNativeDriver: true,
    }).start();
    Animated.parallel([
      Animated.spring(scale, { toValue: 0.98, useNativeDriver: true, speed: 50, bounciness: 0 }),
      Animated.spring(shift, { toValue: 1, useNativeDriver: true, speed: 50, bounciness: 0 }),
    ]).start();
  }

  function up() {
    setPressed(false);
    Animated.parallel([
      Animated.spring(scale, { toValue: 1, useNativeDriver: true, speed: 40, bounciness: 6 }),
      Animated.spring(shift, { toValue: 0, useNativeDriver: true, speed: 40, bounciness: 6 }),
    ]).start();
  }

  return (
    <Pressable onPressIn={down} onPressOut={up} disabled={disabled}
               onPress={disabled ? undefined : onPress}
               style={full ? { alignSelf: "stretch" } : undefined}>
      <Animated.View
        style={[
          s.shadow,
          pressed && s.shadowPressed,
          {
            transform: [
              { scale },
              { translateY: shift.interpolate({ inputRange: [0, 1], outputRange: [0, 1] }) },
            ],
          },
          disabled && { opacity: 0.45 },
          style,
        ]}
      >
        <View style={s.rim}>
          <LiquidSurface tint={tint} tintMix={tintMix} fps={fps} boostRef={boost}
                         style={{ borderRadius: 999 }} />

          <View style={[s.faceWrap, { margin: d.rim }]}>
            <LinearGradient
              colors={pressed ? ["#141414", "#000000"] : ["#202020", "#000000"]}
              start={{ x: 0, y: 0 }} end={{ x: 0, y: 1 }}
              style={[s.face, { paddingVertical: d.padV, paddingHorizontal: d.padH }]}
            >
              <Animated.View
                pointerEvents="none"
                style={[
                  s.wave,
                  {
                    left: spot.x, top: spot.y,
                    opacity: wave.interpolate({ inputRange: [0, 1], outputRange: [0.45, 0] }),
                    transform: [
                      { translateX: -60 }, { translateY: -60 },
                      { scale: wave.interpolate({ inputRange: [0, 1], outputRange: [0.08, 1.5] }) },
                    ],
                  },
                ]}
              />
              {children ?? (
                <Text
                  numberOfLines={1}
                  style={[
                    s.label,
                    { fontSize: d.font, color: active ? "#e8edf7" : "#7b839a" },
                    textStyle,
                  ]}
                >
                  {label}
                </Text>
              )}
            </LinearGradient>
          </View>
        </View>
      </Animated.View>
    </Pressable>
  );
}

const s = StyleSheet.create({
  shadow: {
    shadowColor: "#000", shadowOpacity: 0.5, shadowRadius: 12,
    shadowOffset: { width: 0, height: 7 }, elevation: 7,
  },
  shadowPressed: { shadowOpacity: 0.3, shadowRadius: 4, shadowOffset: { width: 0, height: 1 } },
  rim: { borderRadius: 999, overflow: "hidden", backgroundColor: "#0b0e14" },
  faceWrap: { borderRadius: 999, overflow: "hidden" },
  face: { borderRadius: 999, alignItems: "center", justifyContent: "center", overflow: "hidden" },
  wave: {
    position: "absolute", width: 120, height: 120, borderRadius: 60,
    backgroundColor: "rgba(255,255,255,.30)",
  },
  label: { fontWeight: "600", letterSpacing: 0.2 },
});
