/** Rentgen ryzyka — co z podziału portfela wynika dla wahań.
 *
 *  Sekcja żyje w dwóch miejscach: pod wykresem w Alokacji i jako osobne narzędzie
 *  w zakładce Narzędzia. Dlatego jest samodzielnym komponentem, który sam pobiera
 *  dane i sam pilnuje, żeby nie ruszać serwera, gdy siedzi pod kłódką.
 *
 *  Zasada redakcyjna: każdy wiersz da się rozwinąć i wtedy mówi po polsku, co ta
 *  liczba znaczy dla właściciela portfela — nie definicję ze statystyki.
 */
import React, { useCallback, useEffect, useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, View } from "react-native";
import { AllocationRisk, getAllocationRisk, RiskContribution } from "../../api";
import { useAuth } from "../../auth/AuthContext";
import { openCompany } from "../../companyRouter";
import Logo from "../../components/Logo";
import { usePortfolioVersion } from "../../refresh";
import { C, fmtPLN0, T } from "../../theme";
import { Bar, Card, FadeIn } from "../../ui";

export default function RiskSection() {
  const { locked } = useAuth();
  const isLocked = locked("alloc.risk");
  const [d, setD] = useState<AllocationRisk | null>(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");
  const [open, setOpen] = useState<string | null>(null);

  // te same dane co reszta zakładki — muszą przeliczyć się po imporcie
  const wersja = usePortfolioVersion();
  useEffect(() => {
    if (isLocked) return;
    let alive = true;
    setLoading(true);
    getAllocationRisk()
      .then((r) => { if (alive) setD(r?.empty ? null : r); })
      .catch((e) => { if (alive) setErr(e?.message || "Nie udało się policzyć ryzyka"); })
      .finally(() => { if (alive) setLoading(false); });
    return () => { alive = false; };
  }, [isLocked, wersja]);

  const toggle = useCallback((k: string) => setOpen((o) => (o === k ? null : k)), []);

  if (isLocked) return <RiskSkeleton />;
  if (loading) return <Card style={s.pad}><ActivityIndicator color={C.green} /></Card>;
  if (err) return <Card style={s.pad}><Text style={s.dim}>{err}</Text></Card>;
  if (!d) return <Card style={s.pad}><Text style={s.dim}>Brak danych do policzenia ryzyka.</Text></Card>;

  const c = d.concentration;
  const v = d.volatility;

  return (
    <>
      <Card style={s.pad}>
        <View style={s.metrics}>
          <Metric k="conc" label="Efektywnie pozycji"
                  value={c.effective_n.toLocaleString("pl-PL", { maximumFractionDigits: 1 })}
                  hint={`z ${d.positions} w portfelu`} open={open === "conc"} onPress={toggle}
                  explain={`Gdyby wszystkie Twoje pozycje miały równy udział, portfel zachowywałby się `
                    + `tak, jakbyś miał ich ${c.effective_n.toFixed(1)}. Reszta jest za mała, żeby `
                    + `cokolwiek zmienić. To uczciwsza miara dywersyfikacji niż samo liczenie spółek.`} />
          <Metric k="top1" label="Największa" value={`${c.top1_pct.toFixed(1)}%`}
                  hint="udział jednej pozycji" tone={c.top1_pct > 20 ? C.amber : undefined}
                  open={open === "top1"} onPress={toggle}
                  explain={`Największa pozycja to ${c.top1_pct.toFixed(1)}% portfela, trzy największe `
                    + `razem ${c.top3_pct.toFixed(1)}%, pięć — ${c.top5_pct.toFixed(1)}%. `
                    + `Powyżej 20% w jednej spółce jej pojedynczy zły kwartał widać na całym wyniku.`} />
          <Metric k="vol" label="Zmienność roczna"
                  value={v.annual_pct != null ? `${v.annual_pct.toFixed(1)}%` : "—"}
                  hint={v.sessions ? `${v.sessions} sesji` : "za mało historii"}
                  open={open === "vol"} onPress={toggle}
                  explain={`Typowy rozrzut wyniku w skali roku. ${v.annual_pct != null && v.annual_pct > 25
                    ? "Powyżej 25% to poziom pojedynczych spółek wzrostowych — trzeba mieć mocne nerwy."
                    : "To poziom typowy dla portfela akcyjnego."}`
                    + (v.downside_pct != null
                      ? ` Sama strona spadkowa to ${v.downside_pct.toFixed(1)}% — tyle wynosi zmienność `
                        + "liczona wyłącznie z sesji na minusie, czyli tych, które realnie bolą."
                      : "")} />
          <Metric k="dd" label="Największe obsunięcie"
                  value={v.max_dd_pct != null ? `−${v.max_dd_pct.toFixed(1)}%` : "—"}
                  hint="szczyt → dołek" tone={v.max_dd_pct && v.max_dd_pct > 15 ? C.red : undefined}
                  open={open === "dd"} onPress={toggle}
                  explain={`Najgłębszy zjazd od szczytu w badanym okresie. Tyle trzeba było wytrzymać, `
                    + `nie sprzedając, żeby doczekać odbicia. Najlepszy test na to, czy portfel jest `
                    + `dopasowany do Twojej odporności.`} />
        </View>

        <View style={s.dayRow}>
          <DayStat label="Sesje na plus"
                   value={v.up_days_pct != null ? `${v.up_days_pct.toFixed(0)}%` : "—"} />
          <DayStat label="Najlepszy dzień"
                   value={v.best_day_pct != null ? `+${v.best_day_pct.toFixed(2)}%` : "—"}
                   tone={C.green} />
          <DayStat label="Najgorszy dzień"
                   value={v.worst_day_pct != null ? `${v.worst_day_pct.toFixed(2)}%` : "—"}
                   tone={C.red} />
        </View>

        {v.var95_pln != null && (
          <Text style={s.note}>
            Zły dzień zdarzający się raz na dwadzieścia sesji kosztuje około{" "}
            <Text style={s.b}>{fmtPLN0(v.var95_pln)} zł</Text>. To miara wahań z przeszłości,
            nie prognoza — ale daje pojęcie o skali.
          </Text>
        )}
      </Card>

      {d.warnings.map((w, i) => (
        <FadeIn key={i} delay={i * 60} offset={8}>
          <View style={[s.warn, w.level === "alert" && s.warnHot]}>
            <Text style={[s.warnTxt, w.level === "alert" && { color: C.red }]}>{w.text}</Text>
          </View>
        </FadeIn>
      ))}

      {d.risk_contribution.length > 0 && (
        <Card style={[s.pad, { marginTop: 11 }]}>
          <Text style={s.cardTitle}>Kto robi wahania</Text>
          <Text style={s.cardHint}>
            Udział w pieniądzach kontra udział w ryzyku. Mnożnik powyżej 1 znaczy, że pozycja
            waży w wahaniach więcej, niż zajmuje w portfelu. Dotknij, żeby zobaczyć szczegóły.
          </Text>
          {d.risk_contribution.slice(0, 10).map((r, i) => (
            <ContribRow key={r.ticker} r={r} i={i}
                        open={open === `c${i}`} onPress={() => toggle(`c${i}`)} />
          ))}
        </Card>
      )}

      {d.currency.rows.length > 1 && (
        <Card style={[s.pad, { marginTop: 11 }]}>
          <Text style={s.cardTitle}>Waluty</Text>
          <Text style={s.cardHint}>
            {d.currency.foreign_pct.toFixed(0)}% portfela pracuje poza złotym — tyle zależy
            również od kursu, nie tylko od notowań spółek.
          </Text>
          {d.currency.rows.map((r) => (
            <View key={r.currency} style={s.curRow}>
              <Text style={s.curCode}>{r.currency}</Text>
              <View style={{ flex: 1, marginHorizontal: 12 }}>
                <Bar pct={r.pct} color={r.currency === "PLN" ? C.green : C.violet} />
              </View>
              <Text style={s.curPct}>{r.pct.toFixed(1)}%</Text>
            </View>
          ))}
        </Card>
      )}
    </>
  );
}

/* ------------------------------------------------------------- składowe */

function Metric({ k, label, value, hint, tone, explain, open, onPress }: {
  k: string; label: string; value: string; hint?: string; tone?: string;
  explain: string; open: boolean; onPress: (k: string) => void;
}) {
  return (
    <Pressable style={s.metric} onPress={() => onPress(k)}>
      <View style={{ flexDirection: "row", alignItems: "center", gap: 5 }}>
        <Text style={s.metricLabel}>{label}</Text>
        <Text style={[s.plus, open && { color: C.accent }]}>{open ? "−" : "+"}</Text>
      </View>
      <Text style={[s.metricValue, tone ? { color: tone } : null]}>{value}</Text>
      {!!hint && <Text style={s.metricHint}>{hint}</Text>}
      {open && <Text style={s.metricExplain}>{explain}</Text>}
    </Pressable>
  );
}

function DayStat({ label, value, tone }: { label: string; value: string; tone?: string }) {
  return (
    <View style={{ flex: 1 }}>
      <Text style={s.dayLabel}>{label}</Text>
      <Text style={[s.dayValue, tone ? { color: tone } : null]}>{value}</Text>
    </View>
  );
}

/** Wiersz „kto robi wahania" — logo, paski i rozwijane szczegóły z przejściem do spółki. */
function ContribRow({ r, i, open, onPress }: {
  r: RiskContribution; i: number; open: boolean; onPress: () => void;
}) {
  const hot = (r.ratio ?? 0) > 1.3;
  return (
    <Pressable onPress={onPress} style={s.contribRow}>
      <View style={{ flexDirection: "row", alignItems: "center", gap: 11 }}>
        <Pressable onPress={() => openCompany(r.ticker)} hitSlop={6}>
          <View style={[s.logoRing, hot && { borderColor: "rgba(255,180,84,.5)" }]}>
            <Logo ticker={r.ticker} size={30} />
          </View>
        </Pressable>
        <View style={{ flex: 1 }}>
          <Text style={s.contribTicker} numberOfLines={1}>{r.ticker}</Text>
          <Text style={s.contribName} numberOfLines={1}>{r.name || " "}</Text>
        </View>
        <View style={{ alignItems: "flex-end" }}>
          <Text style={s.contribPct}>{r.risk_pct.toFixed(1)}%</Text>
          {r.ratio != null && (
            <Text style={[s.contribRatio, hot && { color: C.amber }]}>×{r.ratio.toFixed(2)}</Text>
          )}
        </View>
      </View>

      <View style={{ marginTop: 9 }}>
        <Bar pct={Math.max(0, Math.min(100, r.risk_pct))} color={hot ? C.amber : C.accent}
             delay={i * 35} />
      </View>
      <Text style={s.contribMeta}>
        {r.weight_pct.toFixed(1)}% wartości · zmienność {r.vol_pct.toFixed(0)}%
      </Text>

      {open && (
        <View style={s.contribOpen}>
          <Text style={s.contribExplain}>
            {hot
              ? `Ta pozycja zajmuje ${r.weight_pct.toFixed(1)}% portfela, ale odpowiada za `
                + `${r.risk_pct.toFixed(1)}% jego wahań. Pracuje na Ciebie ${r.ratio?.toFixed(2)} raza `
                + "mocniej, niż wskazywałaby jej wielkość — w obie strony."
              : `Wkład w ryzyko (${r.risk_pct.toFixed(1)}%) jest zbliżony do udziału w portfelu `
                + `(${r.weight_pct.toFixed(1)}%). Ta pozycja zachowuje się spokojnie na tle reszty.`}
          </Text>
          <View style={s.grid}>
            <Mini label="Wartość" value={`${fmtPLN0(r.value_pln)} zł`} />
            <Mini label="Dzienne wahanie" value={`± ${fmtPLN0(r.daily_pln)} zł`} />
            <Mini label="Sesje na plus"
                  value={r.up_days_pct != null ? `${r.up_days_pct.toFixed(0)}%` : "—"} />
            <Mini label="Zmienność spadków"
                  value={r.downside_pct != null ? `${r.downside_pct.toFixed(0)}%` : "—"} />
            <Mini label="Najlepszy dzień"
                  value={r.best_day_pct != null ? `+${r.best_day_pct.toFixed(1)}%` : "—"}
                  tone={C.green} />
            <Mini label="Najgorszy dzień"
                  value={r.worst_day_pct != null ? `${r.worst_day_pct.toFixed(1)}%` : "—"}
                  tone={C.red} />
          </View>
          <Pressable onPress={() => openCompany(r.ticker)} style={s.goBtn} hitSlop={6}>
            <Text style={s.goTxt}>Otwórz kartę spółki →</Text>
          </Pressable>
        </View>
      )}
    </Pressable>
  );
}

function Mini({ label, value, tone }: { label: string; value: string; tone?: string }) {
  return (
    <View style={s.mini}>
      <Text style={s.miniLabel}>{label}</Text>
      <Text style={[s.miniValue, tone ? { color: tone } : null]}>{value}</Text>
    </View>
  );
}

/** Szkielet pod kłódką — właściwy kształt, żadnych prawdziwych liczb. */
export function RiskSkeleton() {
  const bar = (w: any, h = 9) => (
    <View style={{ width: w, height: h, borderRadius: 5, backgroundColor: "rgba(255,255,255,.09)" }} />
  );
  return (
    <Card style={s.pad}>
      <View style={s.metrics}>
        {["Efektywnie pozycji", "Największa", "Zmienność roczna", "Największe obsunięcie"].map((l) => (
          <View key={l} style={s.metric}>
            <Text style={s.metricLabel}>{l}</Text>
            <View style={{ marginTop: 6 }}>{bar(56, 19)}</View>
          </View>
        ))}
      </View>
      <View style={{ gap: 14, marginTop: 22 }}>
        {[92, 74, 58, 41].map((w, i) => (
          <View key={i} style={{ flexDirection: "row", alignItems: "center", gap: 11 }}>
            <View style={s.logoRing} />
            <View style={{ flex: 1, gap: 7 }}>
              {bar(90, 8)}
              <Bar pct={w} color={C.accent} />
            </View>
          </View>
        ))}
      </View>
    </Card>
  );
}

const s = StyleSheet.create({
  pad: { padding: 16 },
  dim: { color: C.muted, ...T.small },
  b: { color: C.text, fontWeight: "800" },
  cardTitle: { color: C.text, fontSize: 14, fontWeight: "800" },
  cardHint: { color: C.dim, fontSize: 12, lineHeight: 18, marginTop: 5 },
  note: { color: C.muted, fontSize: 12.3, lineHeight: 19, marginTop: 16 },

  metrics: { flexDirection: "row", flexWrap: "wrap", rowGap: 18 },
  metric: { width: "50%", paddingRight: 10 },
  metricLabel: { color: C.dim, fontSize: 10.5, fontWeight: "700", letterSpacing: 0.5 },
  plus: { color: C.dim, fontSize: 12, fontWeight: "800" },
  metricValue: { color: C.text, fontSize: 21, fontWeight: "800", letterSpacing: -0.6, marginTop: 4 },
  metricHint: { color: C.dim, fontSize: 11, marginTop: 2 },
  metricExplain: {
    color: C.muted, fontSize: 12, lineHeight: 18, marginTop: 9,
    backgroundColor: "rgba(91,140,255,.08)", borderRadius: 10, padding: 10,
  },

  dayRow: {
    flexDirection: "row", gap: 12, marginTop: 20, paddingTop: 16,
    borderTopWidth: 1, borderTopColor: "rgba(33,41,56,.7)",
  },
  dayLabel: { color: C.dim, fontSize: 10.5, fontWeight: "700" },
  dayValue: { color: C.text, fontSize: 15, fontWeight: "800", marginTop: 4 },

  warn: {
    borderWidth: 1, borderColor: "rgba(255,180,84,.3)", backgroundColor: "rgba(255,180,84,.07)",
    borderRadius: 14, padding: 13, marginTop: 10,
  },
  warnHot: { borderColor: "rgba(255,92,108,.35)", backgroundColor: "rgba(255,92,108,.07)" },
  warnTxt: { color: C.amber, fontSize: 12.5, lineHeight: 19 },

  contribRow: {
    paddingVertical: 13, borderBottomWidth: 1, borderBottomColor: "rgba(33,41,56,.6)",
  },
  logoRing: {
    width: 38, height: 38, borderRadius: 19, alignItems: "center", justifyContent: "center",
    borderWidth: 1.5, borderColor: C.border2, overflow: "hidden", backgroundColor: C.elev,
  },
  contribTicker: { color: C.text, fontSize: 13.5, fontWeight: "800" },
  contribName: { color: C.dim, fontSize: 11, marginTop: 2 },
  contribPct: { color: C.text, fontSize: 14, fontWeight: "800" },
  contribRatio: { color: C.dim, fontSize: 11, fontWeight: "700", marginTop: 2 },
  contribMeta: { color: C.dim, fontSize: 11, marginTop: 7 },
  contribOpen: {
    marginTop: 12, backgroundColor: "rgba(255,255,255,.03)", borderRadius: 12, padding: 12,
  },
  contribExplain: { color: C.muted, fontSize: 12.3, lineHeight: 19 },
  grid: { flexDirection: "row", flexWrap: "wrap", marginTop: 12, rowGap: 12 },
  mini: { width: "33.33%", paddingRight: 8 },
  miniLabel: { color: C.dim, fontSize: 9.5, fontWeight: "700" },
  miniValue: { color: C.text, fontSize: 12.5, fontWeight: "800", marginTop: 3 },
  goBtn: { marginTop: 13 },
  goTxt: { color: C.accent, fontSize: 12.5, fontWeight: "700" },

  curRow: { flexDirection: "row", alignItems: "center", marginTop: 13 },
  curCode: { color: C.text, fontSize: 13, fontWeight: "800", width: 42 },
  curPct: { color: C.muted, fontSize: 12.5, fontWeight: "700", width: 48, textAlign: "right" },
});
