/** „Napisz do twórców" — wiadomość premium prosto na skrzynkę zespołu.
 *
 *  Ma wyglądać jak rozmowa, nie formularz: awatar zespołu, powitanie i obietnica
 *  odpowiedzi w 24 h. Treść leci na serwer (`/api/contact`), który przesyła ją
 *  e-mailem i zapisuje kopię. Bez premium serwer oddaje `need_premium` — kierujemy
 *  wtedy na stronę premium.
 */
import { LinearGradient } from "expo-linear-gradient";
import React, { useState } from "react";
import {
  KeyboardAvoidingView, Modal, Platform, Pressable, ScrollView,
  StyleSheet, Text, TextInput, View,
} from "react-native";
import { sendContactMessage } from "../api";
import { C, T } from "../theme";
import { FadeIn, LiquidButton, MetalButton } from "../ui";

import Icon from "../ui/Icon";
const TOPICS = [
  { id: "feature", label: "Brakująca funkcja" },
  { id: "idea", label: "Pomysł" },
  { id: "bug", label: "Coś nie działa" },
  { id: "other", label: "Inne" },
];

export default function ContactScreen({
  onClose, onNeedPremium,
}: {
  onClose: () => void;
  /** wywoływane, gdy konto nie ma premium — otwiera stronę premium */
  onNeedPremium?: () => void;
}) {
  const [topic, setTopic] = useState("feature");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);

  const label = TOPICS.find((t) => t.id === topic)?.label || "";

  async function send() {
    const message = text.trim();
    if (!message || busy) return;
    setBusy(true);
    try {
      const r = await sendContactMessage(message, label);
      if (r.need_premium) {
        onClose();
        onNeedPremium?.();
        return;
      }
      if (r.ok) { setSent(true); return; }
      // serwer bez błędu, ale i bez ok — potraktuj jak nieudane
      setBusy(false);
    } catch {
      setBusy(false);
    }
  }

  return (
    <Modal visible animationType="slide" presentationStyle="pageSheet" onRequestClose={onClose}>
      <View style={s.root}>
        <View style={s.bar}>
          <Text style={s.barTitle}>Napisz do twórców</Text>
          <Pressable onPress={onClose} hitSlop={12} style={s.close}>
            <Icon name="zamknij" size={15} color={C.muted} />
          </Pressable>
        </View>

        <KeyboardAvoidingView
          style={{ flex: 1 }}
          behavior={Platform.OS === "ios" ? "padding" : undefined}
        >
          <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
            {/* nagłówek „rozmowy" — od kogo piszesz i do kogo */}
            <FadeIn>
              <View style={s.who}>
                <LinearGradient
                  colors={[C.gold, C.goldDeep]}
                  start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
                  style={s.avatar}
                >
                  <Icon name="premium" size={21} color="#2a1e05" />
                </LinearGradient>
                <View style={{ flex: 1 }}>
                  <View style={{ flexDirection: "row", alignItems: "center", gap: 7 }}>
                    <Text style={s.whoName}>Zespół Portevo</Text>
                    <View style={s.devTag}><Text style={s.devTagTxt}>DEV</Text></View>
                  </View>
                  <Text style={s.whoSub}>twórcy aplikacji · zwykle odpisujemy w kilka godzin</Text>
                </View>
              </View>
            </FadeIn>

            {/* dymek powitalny od zespołu */}
            <FadeIn delay={80}>
              <View style={s.bubble}>
                <Text style={s.bubbleTxt}>
                  Cześć. Piszesz prosto do nas — małego studia, które robi Portevo.
                  {"\n\n"}Napisz nam, czego brakuje w aplikacji i jakiej funkcji szukasz.
                  Dołożymy wszelkich starań, żeby dodać ją jak najszybciej, jeśli tylko
                  będzie to możliwe.
                  {"\n\n"}<Text style={s.bubbleStrong}>Nie zostawimy Cię bez informacji —
                  obiecujemy, że odpiszemy w przeciągu 24 godzin.</Text>
                </Text>
              </View>
            </FadeIn>

            {sent ? (
              <FadeIn>
                <View style={s.done}>
                  <Icon name="ptaszek" size={30} color={C.green} />
                  <Text style={s.doneTitle}>Wiadomość wysłana</Text>
                  <Text style={s.doneTxt}>
                    Dziękujemy! Przeczytamy ją osobiście i odpiszemy na Twój adres
                    w ciągu 24 godzin.
                  </Text>
                  <MetalButton label="Gotowe" tone="amber" active liquid full
                               style={{ marginTop: 16 }} onPress={onClose} />
                </View>
              </FadeIn>
            ) : (
              <FadeIn delay={140}>
                <Text style={s.lbl}>Czego dotyczy?</Text>
                <View style={s.chips}>
                  {TOPICS.map((t) => (
                    <MetalButton
                      key={t.id} label={t.label} size="sm" tone="amber" round
                      active={topic === t.id} onPress={() => setTopic(t.id)}
                    />
                  ))}
                </View>

                <Text style={s.lbl}>Twoja wiadomość</Text>
                <TextInput
                  style={s.input}
                  value={text}
                  onChangeText={setText}
                  multiline
                  placeholder="Np. Przydałby się alert cenowy dla obserwowanych spółek…"
                  placeholderTextColor={C.dim}
                  maxLength={4000}
                  textAlignVertical="top"
                />
                <Text style={s.count}>{text.length}/4000</Text>

                <LiquidButton
                  label={busy ? "Wysyłam…" : "Wyślij do zespołu"}
                  disabled={busy || !text.trim()}
                  onPress={send}
                  style={{ marginTop: 8 }}
                />
                <Text style={s.note}>
                  Odpowiedź wyślemy na adres Twojego konta. Nie udostępniamy go nikomu.
                </Text>
              </FadeIn>
            )}
          </ScrollView>
        </KeyboardAvoidingView>
      </View>
    </Modal>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg },
  bar: {
    flexDirection: "row", alignItems: "center", justifyContent: "space-between",
    paddingHorizontal: 18, paddingTop: 16, paddingBottom: 12,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  barTitle: { color: C.gold, ...T.micro },
  close: { width: 30, height: 30, alignItems: "center", justifyContent: "center" },
  closeTxt: { color: C.muted, fontSize: 17, fontWeight: "700" },

  wrap: { padding: 18, paddingBottom: 44 },

  who: { flexDirection: "row", alignItems: "center", gap: 13 },
  avatar: {
    width: 52, height: 52, borderRadius: 16, alignItems: "center", justifyContent: "center",
    shadowColor: C.gold, shadowOpacity: 0.5, shadowRadius: 12, shadowOffset: { width: 0, height: 4 },
  },
  avatarTxt: { color: "#2a1e05", fontSize: 24, fontWeight: "800" },
  whoName: { color: C.text, fontSize: 16, fontWeight: "800", letterSpacing: -0.2 },
  devTag: {
    backgroundColor: "rgba(255,210,74,.16)", borderWidth: 1, borderColor: "rgba(255,210,74,.45)",
    borderRadius: 999, paddingHorizontal: 7, paddingVertical: 1.5,
  },
  devTagTxt: { color: C.gold, fontSize: 9, fontWeight: "800", letterSpacing: 0.8 },
  whoSub: { color: C.muted, fontSize: 12, marginTop: 3 },

  bubble: {
    backgroundColor: C.card, borderRadius: 16, borderTopLeftRadius: 5, padding: 16, marginTop: 16,
    borderWidth: 1, borderColor: C.border,
  },
  bubbleTxt: { color: C.text, fontSize: 13.8, lineHeight: 21 },
  bubbleStrong: { color: C.gold, fontWeight: "800" },

  lbl: {
    color: C.muted, fontSize: 10.5, fontWeight: "700", letterSpacing: 0.6,
    textTransform: "uppercase", marginTop: 22, marginBottom: 9,
  },
  chips: { flexDirection: "row", flexWrap: "wrap", gap: 7 },
  input: {
    backgroundColor: C.elev, borderColor: C.border2, borderWidth: 1, borderRadius: 14,
    padding: 14, color: C.text, fontSize: 15, minHeight: 130, lineHeight: 21,
  },
  count: { color: C.dim, fontSize: 11, textAlign: "right", marginTop: 6 },
  note: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 12, textAlign: "center" },

  done: {
    backgroundColor: "rgba(47,212,138,.07)", borderWidth: 1, borderColor: "rgba(47,212,138,.4)",
    borderRadius: 18, padding: 22, alignItems: "center", marginTop: 20,
  },
  doneIcon: { fontSize: 34 },
  doneTitle: { color: C.text, ...T.h2, marginTop: 10 },
  doneTxt: { color: C.muted, fontSize: 13.5, lineHeight: 20, textAlign: "center", marginTop: 8 },
});
