/** Klient API panelu portfela. Adres serwera i token trzymamy w AsyncStorage. */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { accessToken } from "./auth/supabase";

/** Wyjątek z endpointu płatnego — niesie identyfikator funkcji, więc ekran wie,
 *  którą stronę sprzedażową otworzyć. */
export class PremiumRequired extends Error {
  feature: string;
  constructor(feature: string) {
    super("Ta funkcja jest częścią wersji premium");
    this.feature = feature;
  }
}

/** Panel na komputerze jest starszy niż aplikacja.
 *
 *  Aplikacja aktualizuje się sama (Expo), panel trzeba uruchomić ponownie ręcznie —
 *  więc ten rozjazd zdarza się przy każdej nowej funkcji. Gołe „Serwer odpowiedział
 *  404" nie mówi wtedy nic; ten wyjątek mówi wprost, co zrobić.
 */
export class PanelOutdated extends Error {
  constructor() {
    super("Panel na komputerze działa w starszej wersji — uruchom go ponownie "
        + "(skrót „Portevo (telefon)” na pulpicie).");
  }
}

/** Wersja API, której wymaga ta wersja aplikacji. Podbijana razem z `API_VERSION`
 *  w dashboard.py przy dokładaniu endpointów. */
export const REQUIRED_API = 9;

const K_URL = "portfel.baseUrl";
const K_TOKEN = "portfel.token";

/** Adres produkcyjny — wbudowany, żeby aplikacja działała od razu po otwarciu.
 *
 *  Wcześniej pierwszym ekranem był formularz proszący o adres serwera i token.
 *  Dla właściciela łączącego się z własnym komputerem to miało sens; dla kogoś,
 *  kto pierwszy raz otwiera aplikację, to prośba o dane, których nie ma skąd wziąć.
 *  Teraz adres jest znany od startu, a ekran połączenia został w „Więcej" dla tych,
 *  którzy chcą wskazać własny serwer.
 */
/*  Na WEBIE adres liczymy z bieżącej strony, zamiast wpisywać go na sztywno.
 *  Ten sam serwer (dashboard.py) podaje i stronę, i API, więc żądanie z
 *  https://www.portevo.pl idzie do własnego źródła — nie ma zapytania między
 *  domenami, więc CORS w ogóle nie wchodzi w grę. Wpisany na sztywno adres
 *  Railway sprawiał, że po podpięciu domeny cała strona pokazywała
 *  „Failed to fetch": serwer odrzucał obce źródło („Disallowed CORS origin").
 *  Wyjątek to podgląd z `expo start --web` — chodzi na localhost:8081, gdzie
 *  API nie ma, więc tam zostaje adres produkcyjny. */
const webOrigin = (): string | null => {
  if (typeof window === "undefined" || !window.location) return null;
  const { origin, hostname } = window.location;
  if (!origin || /^(localhost|127\.0\.0\.1|\[?::1\]?)$/.test(hostname)) return null;
  return origin;
};

export const DEFAULT_BASE_URL = webOrigin() ?? "https://portfel-production.up.railway.app";

/** Serwer odmówił, bo trzeba być zalogowanym. Niesie sygnał, a nie tekst błędu —
 *  ekran ma otworzyć okno logowania, a nie pokazać czerwony komunikat. */
export class LoginRequired extends Error {
  constructor() {
    super("Zaloguj się, żeby korzystać z tej funkcji");
  }
}

/** Aplikacja pokazuje okno logowania w jednym miejscu (AuthProvider), a odmowa
 *  przychodzi tutaj — w kliencie HTTP. Zamiast przepisywać obsługę 401 w każdym
 *  ekranie z osobna, warstwa konta rejestruje tu jedną funkcję i od tej pory
 *  KAŻDE żądanie odrzucone z braku logowania samo otwiera to okno. */
let loginPrompt: (() => void) | null = null;
export function setLoginPrompt(fn: (() => void) | null) { loginPrompt = fn; }

/** Drobne ustawienia UI trzymane na telefonie (np. tryb „po kosztach"). */
export const getPref = async (key: string, fallback: string) =>
  (await AsyncStorage.getItem(`portfel.${key}`)) ?? fallback;

export const setPref = (key: string, value: string) => {
  // Zapis lokalny jest tym, co się liczy; wysyłka na konto to dodatek, który ma
  // prawo się nie udać. `require` w środku, bo sync sięga z powrotem po ten moduł.
  try { require("./auth/sync").queue(key, value); } catch { /* sync opcjonalny */ }
  return AsyncStorage.setItem(`portfel.${key}`, value);
};

let baseUrl = "";
let token = "";

export async function loadConfig() {
  // Brak zapisanego adresu = zwykły użytkownik, który po prostu otworzył aplikację.
  // Dostaje serwer produkcyjny i wchodzi prosto do środka.
  baseUrl = (await AsyncStorage.getItem(K_URL)) || DEFAULT_BASE_URL;
  token = (await AsyncStorage.getItem(K_TOKEN)) || "";
  return { baseUrl, token };
}

export async function saveConfig(url: string, tok: string) {
  baseUrl = url.trim().replace(/\/+$/, "");
  token = tok.trim();
  await AsyncStorage.multiSet([[K_URL, baseUrl], [K_TOKEN, token]]);
}

export function getConfig() {
  return { baseUrl, token };
}

export async function clearConfig() {
  // Rozłączenie wraca do serwera produkcyjnego, a nie do pustki — inaczej
  // właściciel po odpięciu własnego komputera zostałby z aplikacją bez adresu.
  baseUrl = DEFAULT_BASE_URL;
  token = "";
  await AsyncStorage.multiRemove([K_URL, K_TOKEN]);
}

async function req<T>(path: string, init?: RequestInit, timeoutMs = 25000): Promise<T> {
  if (!baseUrl) throw new Error("Brak adresu serwera");
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    // Token panelu mówi „wolno Ci pukać do tego serwera", token konta — „to ja".
    // Serwer potrzebuje obu: pierwszego do wpuszczenia z sieci, drugiego do premium.
    const bearer = await accessToken().catch(() => "");
    const r = await fetch(baseUrl + path, {
      ...init,
      signal: ctrl.signal,
      headers: {
        ...(init?.headers || {}),
        "X-API-Token": token,
        ...(bearer ? { Authorization: `Bearer ${bearer}` } : {}),
      },
    });
    if (r.status === 401) {
      // Okno logowania otwieramy TYLKO wtedy, gdy użytkownik czegoś chciał.
      // Zapis (POST/DELETE) zawsze jest jego decyzją; przy pobieraniu w tle
      // milczymy, bo inaczej samo wejście do aplikacji witałoby prośbą o konto.
      const zamierzone = Boolean(init?.method && init.method !== "GET");
      if (zamierzone) loginPrompt?.();
      throw new LoginRequired();
    }
    // Każda ścieżka, o którą pyta ta wersja aplikacji, istnieje w aktualnym panelu.
    // 404 znaczy więc jedno: po drugiej stronie chodzi starszy kod.
    if (r.status === 404) throw new PanelOutdated();
    if (r.status === 402) {
      const js = await r.json().catch(() => ({}));
      throw new PremiumRequired(js?.detail?.feature || js?.feature || "");
    }
    if (!r.ok) throw new Error(`Serwer odpowiedział ${r.status}`);
    return (await r.json()) as T;
  } catch (e: any) {
    if (e?.name === "AbortError") throw new Error("Serwer nie odpowiada (timeout)");
    throw e;
  } finally {
    clearTimeout(timer);
  }
}

