export const ping = (url: string, tok: string) =>
  fetch(url.trim().replace(/\/+$/, "") + "/api/portfolio/ping", {
    headers: { "X-API-Token": tok.trim() },
  }).then(async (r) => {
    if (r.status === 401) throw new Error("Błędny token");
    if (!r.ok) throw new Error(`Serwer odpowiedział ${r.status}`);
    const js = await r.json();
    if (!js?.ok) throw new Error("To nie jest serwer portfela");
    return js;
  });

