export type EventDetail = {
  event_id: string;
  category: string;
  description: string;
  /** POSITIVE = odczyt wyższy od prognozy sprzyja walucie kraju */
  rise: string;
  unit: string;
  period: string;
  is_speech: boolean;
  is_report: boolean;
  source_name: string;
  source_url: string;
  history: EconEvent[];
};

export type CalendarQuery = {
  start: string; end: string;
  filter?: string; sort?: string; limit?: number;
  importance?: number; countries?: string[];
  /** „core" = Polska i USA w całości, z reszty świata tylko najwyższa waga
   *  i decyzje o stopach; „all" = bez ograniczenia geograficznego. */
  scope?: "core" | "all";
};

export const getEarningsCalendar = (q: CalendarQuery) => {
  const p = new URLSearchParams({ start: q.start, end: q.end });
  if (q.filter) p.set("filter", q.filter);
  if (q.sort) p.set("sort", q.sort);
  if (q.limit != null) p.set("limit", String(q.limit));
  if (q.importance != null) p.set("importance", String(q.importance));
  if (q.scope) p.set("scope", q.scope);
  if (q.countries?.length) p.set("countries", q.countries.join(","));
  // pierwszy tydzień bez cache to ~30 zapytań do źródeł — dajemy serwerowi czas
  return req<EarningsCalendar>(`/api/earnings/calendar?${p}`, undefined, 90000);
};

