/** Odczyt raportu przez model. Długi timeout — duży plik na mocnym modelu
 *  potrafi zająć minutę, a przerwanie w połowie zmarnowałoby zapytanie. */
export const czytajRaportAi = (nazwa: string, plikB64: string) =>
  req<AiOdczyt>("/api/wealth/ai-report", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ nazwa, plik_b64: plikB64 }),
  }, 180000);

/* ---------- powiadomienia ---------- */

/** Trzy stany z ekranu bota. `strong` = tylko analizy o dużej sile wydźwięku. */
export type TrybNewsow = "off" | "all" | "strong";

export type UstawieniaPowiadomien = {
  news_mode: TrybNewsow;
  earnings_daily: boolean;
  earnings_weekly: boolean;
  push_enabled: boolean;
  email_enabled: boolean;
  /** czy pytaliśmy już o zgodę na e-mail — po to, żeby pytanie nie wracało */
  email_asked: boolean;
  premium: boolean;
  /** czy serwer ma w ogóle skonfigurowaną skrzynkę nadawczą */
  email_available: boolean;
  email_address: string;
};

export type Powiadomienie = {
  id: number;
  kind: "news" | "earnings_today" | "earnings_week";
  title: string;
  body: string;
  symbol: string;
  meta: Record<string, any>;
  read: boolean;
  created_at: string;
};

export const getPowiadomienia = () =>
  req<UstawieniaPowiadomien>("/api/notify/prefs");

export const zapiszPowiadomienia = (zmiany: Partial<UstawieniaPowiadomien>) =>
  req<UstawieniaPowiadomien>("/api/notify/prefs", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify(zmiany),
  });

export const registerDevice = (token: string, platform: string) =>
  req<{ registered: boolean }>("/api/notify/device", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ token, platform }),
  });

export const unregisterDevice = (token: string) =>
  req<{ removed: boolean }>("/api/notify/device/remove", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ token }),
  });

export const getSkrzynka = (limit = 50) =>
  req<{ items: Powiadomienie[]; unread: number }>(`/api/notify/inbox?limit=${limit}`);

export const oznaczPrzeczytane = (ids?: number[]) =>
  req<{ ok: boolean }>("/api/notify/read", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify(ids ? { ids } : {}),
  });

/** Odświeża po stronie serwera listę „moich spółek", z której korzysta silnik
 *  powiadomień. Bez tego świeżo dokupiona spółka jest dla niego niewidoczna. */
export const odswiezMojeSpolki = () =>
  req<{ positions: string[]; watchlist: string[] }>("/api/notify/symbols",
    { method: "POST" }, 40000);

export const testowePowiadomienie = () =>
  req<{ sent: boolean }>("/api/notify/test", { method: "POST" });

/** Notowanie spółki pokazywane przy analizie. */
export type NotowanieSygnalu = {
  symbol: string;
  price: number;
  /** zmiana od poprzedniego zamknięcia, w procentach */
  change_pct: number;
  currency: string;
  market_open: boolean;
  exchange: string;
  /** notowanie poza sesją — jest tylko wtedy, gdy rynek jest zamknięty */
  extended?: { price: number; change_pct: number; phase: "pre" | "post"; ts: number };
};

/** `gpw`: tickery z polskich komunikatów wraz z nazwą spółki z tytułu ESPI.
 *  Serwer pyta wtedy o giełdę warszawską, a przy mikrospółkach szuka kursu
 *  po nazwie — Yahoo ich nie zna, a Biznesradar trzyma je pod nazwą. */
export const getNotowaniaSygnalow = (tickery: string[], gpw: Record<string, string> = {}) => {
  const podpowiedzi = Object.entries(gpw).map(([t, n]) => `${t}:${n}`).join("|");
  return req<{ quotes: Record<string, NotowanieSygnalu>; server_time: number }>(
    `/api/bot/quotes?tickers=${encodeURIComponent(tickery.join(","))}`
    + (podpowiedzi ? `&gpw=${encodeURIComponent(podpowiedzi)}` : ""),
    undefined, 20000);
};
