/** Osie wykresu — „ładne" podziałki i etykiety, które zmieniają się razem z zakresem.
 *
 *  Czas formatujemy przez przesunięcie strefy SERWERA (tzOffset z API), a nie strefy
 *  telefonu — dzięki temu godzina na wykresie zawsze znaczy „czas warszawski",
 *  nawet gdy telefon stoi na innej strefie.
 */

const MONTHS = ["sty", "lut", "mar", "kwi", "maj", "cze",
                "lip", "sie", "wrz", "paź", "lis", "gru"];
const MONTHS_LONG = ["stycznia", "lutego", "marca", "kwietnia", "maja", "czerwca", "lipca",
                     "sierpnia", "września", "października", "listopada", "grudnia"];

/** Podziałki na „okrągłych" wartościach (1 / 2 / 5 / 10 × 10ⁿ) wewnątrz zakresu. */
export function niceTicks(lo: number, hi: number, target = 4): { ticks: number[]; step: number } {
  if (!Number.isFinite(lo) || !Number.isFinite(hi) || hi <= lo) return { ticks: [], step: 1 };
  const raw = (hi - lo) / target;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const norm = raw / mag;
  // najbliższa „ładna" wielokrotność, nie zaokrąglenie w górę — inaczej przy norm
  // tuż powyżej 1 podziałka robi się dwa razy rzadsza, niż prosiliśmy
  const step = (norm < 1.5 ? 1 : norm < 3 ? 2 : norm < 7 ? 5 : 10) * mag;
  const ticks: number[] = [];
  const first = Math.ceil(lo / step - 1e-9) * step;
  for (let v = first; v <= hi + 1e-9; v += step) {
    const t = Math.round(v / step) * step;
    ticks.push(t === 0 ? 0 : t);   // bez tego zero tuż pod zakresem wychodzi jako „-0"
  }
  return { ticks, step };
}

/** Etykieta osi zł — dokładność dobrana do gęstości podziałki (10 zł ≠ 10 tys. zł). */
export function fmtAxisPLN(v: number, step: number): string {
  const a = Math.abs(v);
  if (step >= 1000 && a >= 1000) {
    return (v / 1000).toLocaleString("pl-PL", { maximumFractionDigits: 1 }) + " tys.";
  }
  const dec = step >= 10 ? 0 : step >= 1 ? 0 : step >= 0.1 ? 1 : 2;
  return v.toLocaleString("pl-PL", { minimumFractionDigits: dec, maximumFractionDigits: dec });
}

export const fmtAxisPct = (v: number) =>
  (v > 0 ? "+" : "") + v.toLocaleString("pl-PL", { maximumFractionDigits: 1 }) + "%";

/** Domyślne przesunięcie strefy czasu warszawskiego (w sekundach), gdyby serwer podał 0 */
function warsawOffsetSec(): number {
  try {
    const m = new Date().getMonth();
    return (m >= 3 && m <= 9) ? 7200 : 3600;
  } catch {
    return 7200;
  }
}

const safeOffset = (tzOffset: number) => (tzOffset && Number.isFinite(tzOffset)) ? tzOffset : warsawOffsetSec();

/** Data serwera przełożona na „kalendarz" — czytamy pola UTC z uwzględnieniem przesunięcia strefy. */
const shift = (ts: number, tzOffset: number) => new Date((ts + safeOffset(tzOffset)) * 1000);

export const fmtClock = (ts: number, tzOffset: number) => {
  const d = shift(ts, tzOffset);
  return `${String(d.getUTCHours()).padStart(2, "0")}:${String(d.getUTCMinutes()).padStart(2, "0")}`;
};

/** „5 lipca 2026" — do podpisu dnia sesji. */
export function fmtDayLong(iso: string): string {
  const [y, m, d] = iso.split("-").map(Number);
  if (!y) return iso;
  return `${d} ${MONTHS_LONG[m - 1]} ${y}`;
}

/** „5 lip 2026" — kompaktowo, do kursora na wykresie. */
export function fmtDayShort(iso: string, withYear = false): string {
  if (!iso) return "";                       // punkt poza serią — lepiej pusto niż wywrotka
  const [y, m, d] = iso.split("-").map(Number);
  if (!y) return iso;
  return `${d} ${MONTHS[m - 1]}${withYear ? ` ${y}` : ""}`;
}

export type Tick = { i: number; label: string };

/** Oś czasu sesji: co 30 min / 1 h / 2 h — zależnie od tego, ile trwa. */
export function timeTicks(ts: number[], tzOffset: number, maxTicks = 5): Tick[] {
  if (ts.length < 2) return [];
  const off = safeOffset(tzOffset);
  const span = ts[ts.length - 1] - ts[0];
  const stepSec = [900, 1800, 3600, 7200, 14400, 21600].find((s) => span / s <= maxTicks)
    || 43200;
  const out: Tick[] = [];
  // pierwszy „okrągły" moment po starcie — liczony w czasie serwera
  let t = Math.ceil((ts[0] + off) / stepSec) * stepSec - off;
  let from = 0;
  for (; t <= ts[ts.length - 1]; t += stepSec) {
    while (from < ts.length - 1 && ts[from + 1] <= t) from++;
    const i = ts[from + 1] != null && Math.abs(ts[from + 1] - t) < Math.abs(ts[from] - t)
      ? from + 1 : from;
    if (out.length && out[out.length - 1].i === i) continue;
    out.push({ i, label: fmtClock(t, off) });
  }
  return out;
}

/** Data ISO ze znacznika czasu, w strefie serwera. */
export function isoFromTs(ts: number, tzOffset: number): string {
  const d = shift(ts, tzOffset);
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
}

/** Godziny dla jednej sesji, daty dla dłuższych zakresów — wybór po rozpiętości serii. */
export function autoTicks(ts: number[], tzOffset: number, maxTicks = 5): Tick[] {
  if (ts.length < 2) return [];
  if (ts[ts.length - 1] - ts[0] <= 3 * 86400) return timeTicks(ts, tzOffset, maxTicks);
  return dateTicks(ts.map((t) => isoFromTs(t, tzOffset)), maxTicks);
}

/** Podpis kursora: godzina przy jednej sesji, pełna data przy dłuższych zakresach.
 *
 *  `withClock` jest dla zakresów pośrednich (tydzień, miesiąc) złożonych ze słupków
 *  śróddziennych — tam sama data nie wystarcza, bo na jeden dzień przypada
 *  kilkadziesiąt punktów i bez godziny odczyt byłby nie do rozróżnienia.
 */
export function fmtWhen(ts: number, tzOffset: number, longRange: boolean,
                        withClock = false): string {
  if (!longRange) return fmtClock(ts, tzOffset);
  const day = fmtDayShort(isoFromTs(ts, tzOffset), !withClock);
  return withClock ? `${day}, ${fmtClock(ts, tzOffset)}` : day;
}

/** Oś czasu serii dziennej — dni, miesiące albo lata, zależnie od długości zakresu. */
export function dateTicks(dates: string[], maxTicks = 5): Tick[] {
  const n = dates.length;
  if (n < 2) return [];
  const days = (Date.parse(dates[n - 1]) - Date.parse(dates[0])) / 86400000;

  // dłuższe zakresy dzielimy na granicach kalendarza — etykiety „lip", „2025"
  // trafiają wtedy dokładnie tam, gdzie zaczyna się miesiąc/rok
  const unit = days <= 45 ? "day" : days <= 800 ? "month" : "year";
  if (unit !== "day") {
    const key = (d: string) => (unit === "month" ? d.slice(0, 7) : d.slice(0, 4));
    const bounds: number[] = [];
    for (let i = 1; i < n; i++) if (key(dates[i]) !== key(dates[i - 1])) bounds.push(i);
    if (bounds.length >= 2) {
      const stride = Math.ceil(bounds.length / maxTicks);
      const picked = bounds.filter((_, k) => k % stride === 0);
      const multiYear = dates[0].slice(0, 4) !== dates[n - 1].slice(0, 4);
      return picked.map((i) => ({
        i,
        label: unit === "year"
          ? dates[i].slice(0, 4)
          : MONTHS[Number(dates[i].slice(5, 7)) - 1] +
            (multiYear && dates[i].slice(5, 7) === "01" ? ` ${dates[i].slice(2, 4)}` : ""),
      }));
    }
  }

  // krótkie zakresy (albo za mało granic) — stały krok w dniach, liczony OD KOŃCA,
  // żeby ostatnia etykieta zawsze wypadała na dziś, a odstępy były równe
  const stride = Math.max(1, Math.ceil((n - 1) / Math.max(1, maxTicks - 1)));
  const out: Tick[] = [];
  for (let i = n - 1; i >= 0; i -= stride) out.unshift({ i, label: fmtDayShort(dates[i]) });
  return out;
}
