/** Mózg AI — edycja promptów, kategorii newsów i autorytetu źródeł, na żywo. */
import React, { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator, Alert, StyleSheet, Switch, Text, TextInput, View,
} from "react-native";
import { Brain, getBrain, resetBrain, saveBrain } from "../../api";
import { C, T } from "../../theme";
import { Card, FadeIn, LiquidButton, MetalButton, Press, SectionTitle, Segmented } from "../../ui";
import DecisionPath from "./DecisionPath";

const AREAS = [
  { id: "path", label: "Szlak" },
  { id: "sections", label: "Prompty" },
  { id: "categories", label: "Kategorie" },
  { id: "authority", label: "Autorytet" },
];

export default function BrainTab() {
  const [brain, setBrain] = useState<Brain | null>(null);
  const [area, setArea] = useState("path");
  const [open, setOpen] = useState<string | null>(null);
  const [draft, setDraft] = useState<Record<string, string>>({});
  const [busy, setBusy] = useState("");
  const [err, setErr] = useState("");

  const load = useCallback(async () => {
    try { setBrain(await getBrain()); setErr(""); }
    catch (e: any) { setErr(e?.message || "Nie udało się wczytać Mózgu"); }
  }, []);

  useEffect(() => { load(); }, [load]);

  if (err) {
    return (
      <Card style={s.msg}>
        <Text style={s.msgTitle}>{err}</Text>
        <LiquidButton label="Spróbuj ponownie" full={false} style={{ minWidth: 220 }}
                      onPress={load} />
      </Card>
    );
  }
  if (!brain) {
    return <View style={s.center}><ActivityIndicator color={C.green} size="large" /></View>;
  }

  async function save(updates: Record<string, any>, label: string) {
    setBusy(label);
    try { setBrain(await saveBrain(updates)); }
    catch (e: any) { Alert.alert("Nie zapisano", e?.message || "Błąd połączenia"); }
    finally { setBusy(""); }
  }

  async function doReset(name: string) {
    setBusy(name);
    try {
      setBrain(await resetBrain(name));
      setDraft((d) => { const n = { ...d }; delete n[name]; return n; });
    } catch (e: any) {
      Alert.alert("Nie zresetowano", e?.message || "Błąd połączenia");
    } finally { setBusy(""); }
  }

  const cfg = brain.config;

  return (
    <View>
      <Segmented options={AREAS} value={area} onChange={(a) => { setArea(a); setOpen(null); }} />

      {area === "path" && <DecisionPath brain={brain} />}

      {area === "sections" && (
        <>
          <Text style={s.hint}>
            Instrukcje, które trafiają do modelu przy każdej analizie newsa. Zmiana działa
            natychmiast — następny sygnał będzie oceniony według nowej treści.
          </Text>
          {brain.section_meta.map((m, i) => {
            const value = draft[m.key] ?? cfg.sections[m.key] ?? "";
            const changed = draft[m.key] != null && draft[m.key] !== cfg.sections[m.key];
            const isDefault = (cfg.sections[m.key] || "") === (brain.defaults.sections[m.key] || "");
            return (
              <FadeIn key={m.key} delay={Math.min(i * 25, 200)} offset={8}>
                <Card style={s.card}>
                  <Press onPress={() => setOpen(open === m.key ? null : m.key)} scaleTo={0.99}>
                    <View style={s.cardHead}>
                      <View style={{ flex: 1 }}>
                        <Text style={s.cardTitle}>{m.title}</Text>
                        <Text style={s.cardDesc}>{m.desc}</Text>
                      </View>
                      <View style={{ alignItems: "flex-end", gap: 4 }}>
                        {!isDefault && <View style={s.modTag}><Text style={s.modTxt}>ZMIENIONE</Text></View>}
                        <Text style={s.chevron}>{open === m.key ? "▲" : "▼"}</Text>
                      </View>
                    </View>
                  </Press>

                  {open === m.key && (
                    <View style={{ marginTop: 12 }}>
                      <TextInput
                        style={s.editor}
                        value={value}
                        onChangeText={(t) => setDraft((d) => ({ ...d, [m.key]: t }))}
                        multiline
                        textAlignVertical="top"
                        placeholder="treść instrukcji dla modelu…"
                        placeholderTextColor={C.dim}
                      />
                      <View style={s.actions}>
                        <MetalButton
                          label={busy === m.key ? "Zapisuję…" : "Zapisz"}
                          tone="green" filled style={{ flex: 1 }}
                          disabled={!changed || Boolean(busy)}
                          onPress={() => save({ sections: { [m.key]: value } }, m.key)} />
                        <MetalButton label="Przywróć domyślne" disabled={Boolean(busy)}
                                     onPress={() => doReset(m.key)} />
                      </View>
                    </View>
                  )}
                </Card>
              </FadeIn>
            );
          })}
        </>
      )}

      {area === "categories" && (
        <>
          <Text style={s.hint}>
            Rodzaje newsów, które bot rozpoznaje. Mnożnik skaluje siłę sygnału z danej
            kategorii, a wyłączenie sprawia, że bot ją ignoruje.
          </Text>
          {Object.entries(cfg.categories).map(([key, cat], i) => (
            <FadeIn key={key} delay={Math.min(i * 20, 220)} offset={8}>
              <Card style={s.card}>
                <View style={s.cardHead}>
                  <View style={{ flex: 1, paddingRight: 10 }}>
                    <Text style={s.cardTitle}>{cat.label}</Text>
                    <Text style={s.cardDesc}>{cat.desc}</Text>
                  </View>
                  <Switch
                    value={cat.enabled}
                    onValueChange={(v) =>
                      save({ categories: { [key]: { ...cat, enabled: v } } }, key)}
                    trackColor={{ false: "#2a3247", true: "rgba(47,212,138,.45)" }}
                    thumbColor={cat.enabled ? C.green : "#fff"}
                  />
                </View>
                <MultRow
                  value={cat.mult}
                  disabled={Boolean(busy)}
                  onChange={(v) => save({ categories: { [key]: { ...cat, mult: v } } }, key)}
                />
              </Card>
            </FadeIn>
          ))}
        </>
      )}

      {area === "authority" && (
        <>
          <Text style={s.hint}>
            Kto wypowiedział się w newsie. Im wyższy mnożnik, tym mocniej bot traktuje
            sygnał z tego źródła — słowo prezydenta waży więcej niż wpis anonima.
          </Text>
          {Object.entries(cfg.authority).map(([key, a], i) => (
            <FadeIn key={key} delay={Math.min(i * 20, 220)} offset={8}>
              <Card style={s.card}>
                <Text style={s.cardTitle}>{a.label}</Text>
                <Text style={s.cardDesc}>{a.desc}</Text>
                <MultRow
                  value={a.mult}
                  disabled={Boolean(busy)}
                  onChange={(v) => save({ authority: { [key]: { ...a, mult: v } } }, key)}
                />
              </Card>
            </FadeIn>
          ))}
        </>
      )}

      <SectionTitle hint="Pełna treść, którą model dostaje przy analizie — podgląd tylko do odczytu">
        Gotowy prompt
      </SectionTitle>
      <Card style={s.card}>
        <Text style={s.preview} numberOfLines={open === "__preview" ? undefined : 8}>
          {brain.built?.truth_social || "—"}
        </Text>
        <Press onPress={() => setOpen(open === "__preview" ? null : "__preview")} style={{ marginTop: 10 }}>
          <Text style={s.linkTxt}>{open === "__preview" ? "Zwiń" : "Pokaż całość"}</Text>
        </Press>
      </Card>
    </View>
  );
}

/** Regulacja mnożnika — te same kroki co w panelu web (0,05). */
function MultRow({
  value, onChange, disabled,
}: { value: number; onChange: (v: number) => void; disabled?: boolean }) {
  const set = (v: number) => onChange(Math.max(0, Math.min(3, +v.toFixed(2))));
  return (
    <View style={s.multRow}>
      <Text style={s.multLabel}>Mnożnik siły</Text>
      <View style={s.stepper}>
        <Press style={s.stepBtn} scaleTo={0.88} disabled={disabled}
               onPress={() => set(value - 0.05)}>
          <Text style={s.stepTxt}>−</Text>
        </Press>
        <Text style={[s.multVal, {
          color: value > 1 ? C.green : value < 1 ? C.amber : C.text,
        }]}>
          ×{value.toLocaleString("pl-PL", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
        </Text>
        <Press style={s.stepBtn} scaleTo={0.88} disabled={disabled}
               onPress={() => set(value + 0.05)}>
          <Text style={s.stepTxt}>+</Text>
        </Press>
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  center: { paddingVertical: 60, alignItems: "center" },
  msg: { padding: 24, alignItems: "center", gap: 12 },
  msgTitle: { color: C.text, ...T.body, textAlign: "center" },
  retry: { backgroundColor: C.green, borderRadius: 12, paddingVertical: 11, paddingHorizontal: 22 },
  retryTxt: { color: "#04140c", fontWeight: "800", fontSize: 14 },

  hint: { color: C.dim, fontSize: 12, lineHeight: 18, marginTop: 12, marginBottom: 14, paddingHorizontal: 2 },
  card: { padding: 14, marginBottom: 9 },
  cardHead: { flexDirection: "row", alignItems: "center" },
  cardTitle: { color: C.text, fontSize: 14, fontWeight: "700" },
  cardDesc: { color: C.dim, fontSize: 11.5, lineHeight: 17, marginTop: 4 },
  chevron: { color: C.muted, fontSize: 11 },
  modTag: { backgroundColor: "rgba(167,139,250,.16)", borderRadius: 5, paddingHorizontal: 6, paddingVertical: 2 },
  modTxt: { color: C.violet, fontSize: 8.5, fontWeight: "800", letterSpacing: 0.4 },

  editor: {
    backgroundColor: C.bg, borderColor: C.border2, borderWidth: 1, borderRadius: 12,
    padding: 12, color: C.text, fontSize: 13, lineHeight: 19, minHeight: 190,
  },
  actions: { flexDirection: "row", gap: 9, marginTop: 11 },
  saveBtn: { backgroundColor: C.green, borderRadius: 11, paddingVertical: 11, paddingHorizontal: 22 },
  saveTxt: { color: "#04140c", fontWeight: "800", fontSize: 13 },
  resetBtn: {
    borderWidth: 1, borderColor: C.border2, borderRadius: 11, paddingVertical: 11, paddingHorizontal: 16,
  },
  resetTxt: { color: C.muted, fontWeight: "700", fontSize: 13 },

  multRow: {
    flexDirection: "row", alignItems: "center", justifyContent: "space-between", marginTop: 12,
  },
  multLabel: { color: C.muted, fontSize: 12.5, fontWeight: "600" },
  stepper: { flexDirection: "row", alignItems: "center", gap: 4 },
  stepBtn: {
    width: 32, height: 32, borderRadius: 9, backgroundColor: C.elev,
    borderWidth: 1, borderColor: C.border2, alignItems: "center", justifyContent: "center",
  },
  stepTxt: { color: C.text, fontSize: 17, fontWeight: "800", lineHeight: 20 },
  multVal: { fontSize: 14, fontWeight: "800", minWidth: 56, textAlign: "center" },

  preview: { color: C.muted, fontSize: 11.5, lineHeight: 17.5 },
  linkTxt: { color: C.accent, fontSize: 12.5, fontWeight: "700" },
});
