/** Duża akcja ekranu w metalowej pigułce — ta sama konstrukcja co `LiquidPill`,
 *  tylko w rozmiarze głównego przycisku i na całą szerokość.
 */
import React from "react";
import { TextStyle, ViewStyle } from "react-native";
import LiquidPill from "./LiquidPill";

export default function LiquidButton({
  label, onPress, tint = "#9fb2d0", disabled = false, full = true, fps = 30, style, textStyle,
}: {
  label: string;
  onPress?: () => void;
  tint?: string;
  disabled?: boolean;
  full?: boolean;
  fps?: number;
  style?: ViewStyle;
  textStyle?: TextStyle;
}) {
  return (
    <LiquidPill
      label={label} size="lg" active full={full} fps={fps}
      tint={tint} tintMix={0.22} disabled={disabled} onPress={onPress}
      style={style} textStyle={{ fontSize: 16, fontWeight: "700", ...(textStyle as object) }}
    />
  );
}
