/** Kalendarz wydarzeń — co się dzieje dziś i co dopiero będzie.
 *
 *  Każdy wiersz ma komplet akcji z dawnego panelu webowego: śledzenie,
 *  priorytet ⚡ (szybszy nasłuch), ręczny start/stop sesji, podmianę adresu
 *  streamu, otwarcie strony źródłowej i usunięcie.
 *
 *  Adres streamu edytujemy w rozwijanym polu, a nie w systemowym okienku —
 *  `prompt()` nie istnieje na telefonie, a Alert.prompt działa tylko na iOS.
 */
import React, { useState } from "react";
import {
  ActivityIndicator, Linking, Platform, Pressable, StyleSheet, Switch, Text,
  TextInput, View,
} from "react-native";
import {
  liveAddEvent, liveDeleteEvent, liveDiscover, liveEnrich, livePriority, liveRefresh,
  liveSessionStart, liveSessionStop, liveStreamUrl, liveTrack, LiveEvent, LiveState,
} from "../../../api";
import { C, T } from "../../../theme";
import { Card, FadeIn, MetalButton, Press } from "../../../ui";
import { dayLabel, shiftDate, todayISO } from "./dates";

import Icon from "../../../ui/Icon";
const CATEGORY: Record<string, { label: string; color: string }> = {
  trump: { label: "TRUMP", color: "#ff5c6c" },
  fed: { label: "FED", color: "#ffb454" },
  fda: { label: "FDA", color: "#38bdf8" },
  earnings: { label: "WYNIKI", color: "#2fd48a" },
  macro: { label: "MAKRO", color: "#8b5cf6" },
  manual: { label: "WŁASNE", color: "#8b93a7" },
};
const cat = (k?: string) =>
  CATEGORY[k || ""] || { label: (k || "INNE").toUpperCase().slice(0, 8), color: C.muted };

const CATEGORIES = ["trump", "fed", "fda", "earnings", "macro", "manual"];

type Props = {
  st: LiveState; date: string; busy: string;
  act: (label: string, fn: () => Promise<any>) => Promise<any>;
  onDate: (d: string) => void;
};

export default function EventsTab({ st, date, busy, act, onDate }: Props) {
  const [editUrl, setEditUrl] = useState<string | null>(null);
  const [urlDraft, setUrlDraft] = useState("");
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState({ title: "", time: "", url: "", category: "manual" });

  const events = st.events || [];
  const sessions = st.sessions || [];
  const sessionOf = (id: string) => sessions.find((x) => x.id === id);

  const discover = () => act("discover", async () => {
    const r1 = await liveDiscover(2);
    if (r1?.error) throw new Error(r1.error);
    // etap 2 dokłada godziny i adresy — bez niego wydarzenia bywają bez streamu
    const r2 = await liveEnrich(2);
    return { ...r1, ...r2 };
  });

  const submitAdd = () => {
    if (!form.title.trim()) return;
    act("add", () => liveAddEvent({
      title: form.title.trim(), date,
      time: form.time.trim() || undefined,
      stream_url: form.url.trim(), category: form.category,
    })).then(() => {
      setForm({ title: "", time: "", url: "", category: "manual" });
      setAdding(false);
    });
  };

  return (
    <View>
      {/* --------- wybór dnia --------- */}
      <View style={s.dateRow}>
        <Press style={s.dateBtn} onPress={() => onDate(shiftDate(date, -1))}>
          <Text style={s.dateBtnTxt}>‹</Text>
        </Press>
        <Pressable style={s.dateMid} onPress={() => onDate(todayISO())}>
          <Text style={s.dateLabel}>{dayLabel(date)}</Text>
          <Text style={s.dateIso}>{date}</Text>
        </Pressable>
        <Press style={s.dateBtn} onPress={() => onDate(shiftDate(date, 1))}>
          <Text style={s.dateBtnTxt}>›</Text>
        </Press>
      </View>

      {/* --------- akcje na kalendarzu --------- */}
      <View style={s.actions}>
        <MetalButton size="sm" label={busy === "refresh" ? "Odświeżam…" : "Odśwież źródła"}
                     onPress={() => act("refresh", liveRefresh)} />
        <MetalButton size="sm" tone="blue"
                     label={busy === "discover" ? "AI szuka… (do 2 min)" : "Szukaj w internecie"}
                     onPress={discover} />
        <MetalButton size="sm" label={adding ? "Anuluj" : "+ Dodaj ręcznie"}
                     onPress={() => setAdding((v) => !v)} />
      </View>
      {busy === "discover" && (
        <Text style={s.hint}>
          Model przeszukuje internet i dopisuje wydarzenia, potem uzupełnia godziny
          i adresy streamów. Potrafi to potrwać — możesz zamknąć panel, robota leci dalej.
        </Text>
      )}

      {/* --------- ręczne dodanie --------- */}
      {adding && (
        <FadeIn>
          <Card style={s.form}>
            <TextInput style={s.input} placeholder="Tytuł, np. Konferencja EBC"
                       placeholderTextColor={C.dim} value={form.title}
                       onChangeText={(v) => setForm({ ...form, title: v })} />
            <TextInput style={s.input} placeholder="Godzina, np. 14:30"
                       placeholderTextColor={C.dim} value={form.time}
                       onChangeText={(v) => setForm({ ...form, time: v })} />
            <TextInput style={s.input} placeholder="Adres streamu (YouTube / webcast)"
                       placeholderTextColor={C.dim} autoCapitalize="none" value={form.url}
                       onChangeText={(v) => setForm({ ...form, url: v })} />
            <View style={s.chips}>
              {CATEGORIES.map((k) => {
                const c = cat(k);
                const on = form.category === k;
                return (
                  <Press key={k} onPress={() => setForm({ ...form, category: k })}
                         style={[s.chip, on && { borderColor: c.color, backgroundColor: c.color + "22" }]}>
                    <Text style={[s.chipTxt, on && { color: c.color }]}>{c.label}</Text>
                  </Press>
                );
              })}
            </View>
            <MetalButton size="sm" tone="green"
                         label={busy === "add" ? "Dodaję…" : "Dodaj wydarzenie"}
                         onPress={submitAdd} />
          </Card>
        </FadeIn>
      )}

      {/* --------- lista --------- */}
      {events.length === 0 ? (
        <Card style={s.empty}>
          <Text style={s.emptyTxt}>
            Brak wydarzeń na ten dzień. Odśwież źródła, poszukaj przez AI albo dodaj ręcznie.
          </Text>
        </Card>
      ) : (
        events.map((e, i) => (
          <EventRow
            key={e.id} ev={e} delay={i * 22} busy={busy}
            running={Boolean(sessionOf(e.id)?.running)}
            editing={editUrl === e.id}
            urlDraft={urlDraft}
            onUrlDraft={setUrlDraft}
            onEdit={() => { setEditUrl(editUrl === e.id ? null : e.id); setUrlDraft(e.stream_url || ""); }}
            onSaveUrl={() => act(e.id, () => liveStreamUrl(e.id, urlDraft)).then(() => setEditUrl(null))}
            onTrack={() => act(e.id, () => liveTrack(e.id, !e.tracked))}
            onPriority={() => act(e.id, () => livePriority(e.id, e.priority !== "high"))}
            onSession={() => act(e.id, () =>
              sessionOf(e.id)?.running ? liveSessionStop(e.id) : liveSessionStart(e.id))}
            onDelete={() => act(e.id, () => liveDeleteEvent(e.id))}
          />
        ))
      )}
    </View>
  );
}

function EventRow({
  ev, delay, busy, running, editing, urlDraft, onUrlDraft,
  onEdit, onSaveUrl, onTrack, onPriority, onSession, onDelete,
}: {
  ev: LiveEvent; delay: number; busy: string; running: boolean; editing: boolean;
  urlDraft: string; onUrlDraft: (v: string) => void;
  onEdit: () => void; onSaveUrl: () => void; onTrack: () => void;
  onPriority: () => void; onSession: () => void; onDelete: () => void;
}) {
  const c = cat(ev.category);
  const isLive = ev.status === "live";
  const ended = ev.status === "ended";
  const hot = ev.priority === "high";
  const working = busy === ev.id;

  return (
    <FadeIn delay={Math.min(delay, 240)} offset={8}>
      <Card style={[s.row, isLive && s.rowLive]}>
        <View style={s.rowTop}>
          <Text style={s.time}>{ev.time || "—"}</Text>
          <View style={[s.badge, { backgroundColor: c.color + "22", borderColor: c.color + "55" }]}>
            <Text style={[s.badgeTxt, { color: c.color }]}>{c.label}</Text>
          </View>
          {isLive && (
            <View style={s.liveTag}>
              <View style={s.liveDot} />
              <Text style={s.liveTxt}>NA ŻYWO</Text>
            </View>
          )}
          {ended && <Text style={s.ended}>zakończone</Text>}
          {running && <Text style={s.rec}>● słucham</Text>}
          {working && <ActivityIndicator size="small" color={C.green} style={{ marginLeft: 6 }} />}
        </View>

        <Text style={s.title} numberOfLines={3}>{ev.title}</Text>
        {!ev.stream_url && !isLive && (
          <View style={s.warnRow}>
            <Icon name="uwaga" size={12} color={C.amber} />
            <Text style={s.warn}>brak adresu streamu — dodaj ołówkiem albo znajdzie go wyszukiwanie AI</Text>
          </View>
        )}
        {!!ev.note && <Text style={s.note} numberOfLines={2}>{ev.note}</Text>}
        {!!(ev as any).context && (
          <View style={s.contextRow}>
            <Icon name="ai" size={12} color={C.violet} />
            <Text style={s.context} numberOfLines={3}>{(ev as any).context}</Text>
          </View>
        )}

        <View style={s.rowActions}>
          <View style={s.trackBox}>
            <Text style={s.trackLabel}>śledź</Text>
            <Switch value={Boolean(ev.tracked)} onValueChange={onTrack}
                    trackColor={{ false: "#2a3247", true: "rgba(47,212,138,.5)" }}
                    thumbColor={ev.tracked ? C.green : "#fff"} />
          </View>

          <Press onPress={onPriority}
                 style={[s.iconBtn, hot && { borderColor: C.amber, backgroundColor: "rgba(255,180,84,.16)" }]}>
            <Icon name="szybko" size={14} color={hot ? C.amber : C.muted} />
          </Press>

          <Press onPress={onEdit} style={s.iconBtn}><Icon name="recznie" size={14} color={C.muted} /></Press>

          {!!ev.url && (
            <Press onPress={() => Linking.openURL(ev.url!)} style={s.iconBtn}>
              <Text style={s.iconTxt}>↗</Text>
            </Press>
          )}

          <Press onPress={onDelete} style={s.iconBtn}><Icon name="kosz" size={14} color={C.muted} /></Press>

          <View style={{ marginLeft: "auto" }}>
            <MetalButton size="sm" tone={running ? "red" : "green"}
                         label={running ? "■ Stop" : "▶ Słuchaj"} onPress={onSession} />
          </View>
        </View>

        {editing && (
          <View style={s.editRow}>
            <TextInput style={[s.input, { flex: 1, marginBottom: 0 }]} value={urlDraft}
                       onChangeText={onUrlDraft} autoCapitalize="none"
                       placeholder="https://youtube.com/watch?v=…" placeholderTextColor={C.dim} />
            <MetalButton size="sm" tone="green" label="Zapisz" onPress={onSaveUrl} />
          </View>
        )}
      </Card>
    </FadeIn>
  );
}

const s = StyleSheet.create({
  dateRow: { flexDirection: "row", alignItems: "center", gap: 10, marginBottom: 12 },
  dateBtn: {
    width: 42, height: 42, borderRadius: 12, backgroundColor: C.card,
    borderWidth: 1, borderColor: C.border, alignItems: "center", justifyContent: "center",
  },
  dateBtnTxt: { color: C.text, fontSize: 20, lineHeight: 22 },
  dateMid: { flex: 1, alignItems: "center" },
  dateLabel: { color: C.text, fontSize: 15, fontWeight: "800" },
  dateIso: { color: C.dim, fontSize: 11, marginTop: 2 },

  actions: { flexDirection: "row", flexWrap: "wrap", gap: 8, marginBottom: 10 },
  hint: { color: C.muted, fontSize: 11.5, lineHeight: 16.5, marginBottom: 10 },

  form: { padding: 14, marginBottom: 12, gap: 10 },
  input: {
    backgroundColor: C.elev, borderWidth: 1, borderColor: C.border2, borderRadius: 11,
    color: C.text, fontSize: 13, paddingHorizontal: 12,
    paddingVertical: Platform.OS === "ios" ? 11 : 8, marginBottom: 2,
  },
  chips: { flexDirection: "row", flexWrap: "wrap", gap: 7 },
  chip: {
    paddingHorizontal: 10, paddingVertical: 6, borderRadius: 9,
    borderWidth: 1, borderColor: C.border2,
  },
  chipTxt: { color: C.muted, fontSize: 10.5, fontWeight: "700" },

  row: { padding: 13, marginBottom: 9 },
  rowLive: { borderColor: "rgba(255,92,108,.45)", borderWidth: 1 },
  rowTop: { flexDirection: "row", alignItems: "center", gap: 8 },
  time: { color: C.text, fontSize: 13, fontWeight: "800" },
  badge: { borderRadius: 6, borderWidth: 1, paddingHorizontal: 7, paddingVertical: 3 },
  badgeTxt: { fontSize: 9.5, fontWeight: "800", letterSpacing: 0.4 },
  liveTag: {
    flexDirection: "row", alignItems: "center", gap: 4,
    backgroundColor: "rgba(255,92,108,.16)", paddingHorizontal: 7, paddingVertical: 3,
    borderRadius: 6,
  },
  liveDot: { width: 6, height: 6, borderRadius: 3, backgroundColor: C.red },
  liveTxt: { color: C.red, fontSize: 9.5, fontWeight: "800" },
  ended: { color: C.dim, fontSize: 10.5 },
  rec: { color: C.green, fontSize: 10.5, fontWeight: "700" },

  title: { color: C.text, fontSize: 13.5, lineHeight: 19, marginTop: 9 },
  warnRow: { flexDirection: "row", alignItems: "flex-start", gap: 5, marginTop: 5 },
  warn: { flex: 1, color: C.amber, fontSize: 10.5, lineHeight: 15 },
  note: { color: C.dim, fontSize: 11, marginTop: 5, lineHeight: 15 },
  contextRow: { flexDirection: "row", alignItems: "flex-start", gap: 5, marginTop: 5 },
  context: { flex: 1, color: "#a78bfa", fontSize: 11, lineHeight: 15.5 },

  rowActions: { flexDirection: "row", alignItems: "center", gap: 7, marginTop: 12 },
  trackBox: { flexDirection: "row", alignItems: "center", gap: 5 },
  trackLabel: { color: C.dim, fontSize: 10.5 },
  iconBtn: {
    width: 34, height: 32, borderRadius: 9, borderWidth: 1, borderColor: C.border2,
    alignItems: "center", justifyContent: "center",
  },
  iconTxt: { color: C.muted, fontSize: 13 },

  editRow: { flexDirection: "row", alignItems: "center", gap: 8, marginTop: 10 },

  empty: { padding: 20 },
  emptyTxt: { color: C.dim, fontSize: 12.5, lineHeight: 18 },
});
