/** Przegląd — wartość portfela, wykres z zakresami (z sesją dnia), statystyki, pozycje. */
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator, AppState, RefreshControl, ScrollView, StyleSheet, Text, View,
} from "react-native";
import {
  getHistory, getIntraday, getPref, getSeries, getSummary, getWatchlist, History, Intraday,
  refresh, Series, setPref, Summary, WatchItem,
} from "../api";
import { useAuth } from "../auth/AuthContext";
import { chartHeight, useLayout, TAB_SPACE } from "../layout";
import { fmtClock, fmtDayLong } from "../chartAxis";
import { BrandFooter, BrandLogo } from "../components/Brand";
import ChartFullscreen from "../components/ChartFullscreen";
import Watchlist from "../components/Watchlist";
import CompanyScreen from "./CompanyScreen";
import LiveBar from "../components/LiveBar";
import Logo from "../components/Logo";
import PortfolioChart, { ChartMode } from "../components/PortfolioChart";
import ReportUpload from "../components/ReportUpload";
import WealthSection from "../components/WealthSection";
import { usePortfolioVersion } from "../refresh";
import { C, fmtPct, fmtPLN, fmtPLN0, plColor, plural, sgnPLN, T } from "../theme";
import {
  Card, FadeIn, LiquidButton, MetalButton, Press, RefreshButton, SectionTitle, Segmented,
} from "../ui";

const MODES = [
  { id: "value", label: "Wartość" },
  { id: "candle", label: "Świece" },
  { id: "compare", label: "Porównanie" },
];

/** Benchmarki — te same co w panelu web, z kolorami do legendy wykresu. */
const BENCH: Record<string, { label: string; color: string }> = {
  sp500: { label: "S&P 500", color: "#5b8cff" },
  nasdaq100: { label: "Nasdaq 100", color: "#67e8f9" },
  wig20: { label: "WIG20 TR", color: "#ffb454" },
  inflation: { label: "Inflacja PL", color: "#a78bfa" },
  gold: { label: "Złoto", color: "#e6c15a" },
  btc: { label: "Bitcoin", color: "#f7931a" },
  usd: { label: "Dolar", color: "#9aa7c7" },
};

/** „1D" idzie osobną ścieżką (dane śróddzienne), reszta to seria dzienna. */
const DAY = "1d";

/** Zakresy rysowane ze słupków śróddziennych zamiast z wyceny dziennej.
 *
 *  Zakres zostaje ten sam, zmienia się wyłącznie szczegółowość — tydzień z wyceny
 *  dziennej to 7 punktów, z czego weekend jest powtórką piątku. Serwer sam decyduje,
 *  czy da radę (Yahoo ma darmowe słupki godzinowe tylko 2 lata wstecz); gdy odmówi,
 *  wracamy do serii dziennej bez żadnej zmiany w UI.
 *
 *  Wyjątek to „Porównanie": TWR i benchmarki są liczone na siatce dni i tam
 *  szczegółowość śróddzienna nic nie wnosi.
 */
const INTRA = new Set(["1w", "1m", "3m", "6m", "ytd", "1y", "3y", "max"]);

/** Następny dłuższy zakres. Gdy palec dojedzie do początku wykresu i ciągnie dalej
 *  w przeszłość, dosypujemy historii zamiast zatrzymywać się na wybranym zakresie —
 *  „6M" mówi, ile danych mamy pobranych, a nie dokąd wolno patrzeć. */
const LONGER: Record<string, string> = {
  "1d": "1w", "1w": "1m", "1m": "3m", "3m": "6m", "6m": "1y", ytd: "1y", "1y": "3y", "3y": "max",
};
const RANGES = [
  { id: DAY, label: "1D", name: "dzisiaj" },
  { id: "1w", label: "1T", name: "tydzień" },
  { id: "1m", label: "1M", name: "miesiąc" },
  { id: "3m", label: "3M", name: "3 miesiące" },
  { id: "6m", label: "6M", name: "pół roku" },
  { id: "ytd", label: "YTD", name: "od początku roku" },
  { id: "1y", label: "1R", name: "rok" },
  { id: "3y", label: "3L", name: "3 lata" },
  { id: "max", label: "MAX", name: "od początku" },
];

type SortKey = "value" | "pl" | "pct" | "name";

export default function OverviewScreen() {
  const { wide, column } = useLayout();
  const { user } = useAuth();
  const [summary, setSummary] = useState<Summary | null>(null);
  const [series, setSeries] = useState<Series | null>(null);
  const [day, setDay] = useState<Intraday | null>(null);
  // seria śróddzienna dla zakresów z INTRA — trzymana obok serii dziennej, bo
  // porównanie z rynkiem i tak potrzebuje siatki dni (TWR, benchmarki)
  const [hist, setHist] = useState<History | null>(null);
  const [range, setRange] = useState("max");
  const [mode, setMode] = useState<ChartMode>("value");
  // podbicie kasuje przybliżenie wykresu; robimy to tylko przy ŚWIADOMEJ zmianie
  // zakresu, a nie przy cichym odświeżaniu kursów co pół minuty
  const [reset, setReset] = useState(0);
  const [bench, setBench] = useState<string[]>([]);
  const [sort, setSort] = useState<SortKey>("value");
  // „po kosztach" = wartość i wyniki pomniejszone o to, co zapłacimy przy wyjściu
  // (prowizja od sprzedaży + zamiana walut na PLN). Wybór zostaje na telefonie.
  const [net, setNet] = useState(true);
  // dolna część ekranu: nasze pozycje albo obserwowane spółki z całego świata
  const [tab, setTab] = useState<"positions" | "watch">("positions");
  const [watch, setWatch] = useState<WatchItem[]>([]);
  const [watchBusy, setWatchBusy] = useState(false);
  const [openSymbol, setOpenSymbol] = useState<string | null>(null);
  // wykres na cały ekran — ten sam stan (zakres, tryb, benchmarki), tylko duży
  const [fullscreen, setFullscreen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [switching, setSwitching] = useState(false);
  // osobno od `switching`: przy zmianie benchmarku wykres ZOSTAJE na ekranie,
  // migocze tylko delikatnie — podmiana go na kręciołek przy każdym kliknięciu
  // w legendę byłaby gorsza niż samo czekanie
  const [benchBusy, setBenchBusy] = useState(false);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const isDay = range === DAY;

  // benchmarki pobieramy razem z serią — backend zwraca je znormalizowane do zakresu
  const benchRef = useRef(bench);
  benchRef.current = bench;

  /** Numer ostatniego zamówienia. Odpowiedź ze starszym numerem WYRZUCAMY.
   *
   *  Bez tego przełączanie benchmarków wyglądało jak zawieszenie: klikasz złoto,
   *  nic się nie dzieje, odklikujesz — i po chwili złoto samo się pojawia. To nie
   *  była awaria, tylko spóźniona odpowiedź na kliknięcie, które już nie
   *  obowiązywało. Sieć nie gwarantuje kolejności; gwarantujemy ją tutaj.
   *  (To ten sam wzorzec, co `ignore` z dokumentacji Reacta, przystosowany do
   *  wywołań z obsługi zdarzeń zamiast z useEffect.)
   */
  const zamowienie = useRef(0);

  /** Co dociągnąć. Domyślnie wszystko; przy zmianie samego benchmarku — tylko seria.
   *
   *  Zmiana benchmarku nie wpływa ani na podsumowanie, ani na przebieg śróddzienny,
   *  a to właśnie przebieg śróddzienny jest najdroższym zapytaniem na tym ekranie.
   *  Ściąganie go przy każdym kliknięciu w „Złoto" było czystą stratą.
   */
  const load = useCallback(async (
    r: string, opcje: { summary?: boolean; detail?: boolean } = {},
  ) => {
    const { summary: chceSum = true, detail: chceDetail = true } = opcje;
    const moje = ++zamowienie.current;
    setErr("");
    try {
      const [sum, data, detail] = await Promise.all([
        chceSum ? getSummary() : Promise.resolve(null),
        r === DAY ? getIntraday() : getSeries(r, benchRef.current),
        // szczegółowy przebieg jest dodatkiem do serii dziennej, nie zamiennikiem —
        // gdy się nie uda (brak notowań, stary serwer), zostaje wykres dzienny
        chceDetail && INTRA.has(r) ? getHistory(r).catch(() => null) : Promise.resolve(null),
      ]);
      if (moje !== zamowienie.current) return;      // w międzyczasie kliknięto co innego
      if (sum) setSummary(sum as Summary);
      if (r === DAY) setDay(data as Intraday);
      else setSeries(data as Series);
      if (chceDetail) setHist(detail && !detail.empty ? detail : null);
    } catch (e: any) {
      if (moje !== zamowienie.current) return;
      setErr(e?.message || "Błąd połączenia");
    } finally {
      if (moje === zamowienie.current) {
        setLoading(false);
        setSwitching(false);
        setBenchBusy(false);
      }
    }
  }, []);

  useEffect(() => { load(range); }, []);
  useEffect(() => { getPref("netMode", "1").then((v) => setNet(v === "1")); }, []);

  const loadWatch = useCallback(async () => {
    setWatchBusy(true);
    try { setWatch(await getWatchlist()); }
    catch { /* pusty stan pokaże się sam */ } finally { setWatchBusy(false); }
  }, []);

  function pickTab(t: "positions" | "watch") {
    setTab(t);
    if (t === "watch" && !watch.length) loadWatch();
  }

  function toggleNet() {
    setNet((v) => {
      setPref("netMode", v ? "0" : "1");
      return !v;
    });
  }

  // Ciche odświeżanie: kursy same się aktualizują, dopóki aplikacja jest na wierzchu.
  // Pauzujemy w tle, żeby nie zużywać baterii i transferu.
  const rangeRef = useRef(range);
  rangeRef.current = range;

  // Raport wgrany na INNEJ zakładce („Więcej") albo zmiana zalogowanego konta.
  // Ten ekran ma wprawdzie własne odświeżanie co 30 s, ale czekanie pół minuty
  // na efekt wgrania raportu wygląda dokładnie jak awaria.
  const wersja = usePortfolioVersion();
  const pierwszaWersja = useRef(wersja);
  useEffect(() => {
    if (wersja === pierwszaWersja.current) return;
    setLoading(true);
    load(rangeRef.current);
  }, [wersja, load]);

  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (timer) return;
      timer = setInterval(() => load(rangeRef.current), 30000);
    };
    const stop = () => { if (timer) { clearInterval(timer); timer = null; } };
    const sub = AppState.addEventListener("change", (st) => {
      if (st === "active") { load(rangeRef.current); start(); } else stop();
    });
    start();
    return () => { stop(); sub.remove(); };
  }, [load]);

  async function pickRange(r: string) {
    if (r === range) return;
    setRange(r);
    setReset((k) => k + 1);       // świadomy wybór zakresu kasuje przybliżenie
    // pierwsze wejście w dany tryb nie ma jeszcze danych — pokaż kręciołek w karcie
    if ((r === DAY && !day) || (r !== DAY && !series)
        || (INTRA.has(r) && hist?.range !== r)) setSwitching(true);
    await load(r, { summary: false });
  }

  /** Wykres poprosił o dane sprzed początku serii.
   *
   *  W przeciwieństwie do `pickRange` NIE podmieniamy wykresu na kręciołek i nie
   *  ruszamy `reset` — stary przebieg zostaje na ekranie, a gdy przyjdzie dłuższy,
   *  wykres sam wróci w oglądane miejsce w czasie. Dla użytkownika wygląda to jak
   *  zwykłe przesuwanie, tyle że historia się nie kończy.
   */
  function extendRange() {
    const next = LONGER[rangeRef.current];
    if (!next || next === rangeRef.current) return;
    setRange(next);
    load(next, { summary: false });
  }

  function pickMode(m: ChartMode) {
    setMode(m);
    // pierwsze wejście w porównanie bez wybranego benchmarku — podpowiedz S&P 500
    if (m === "compare" && bench.length === 0) {
      setBench(["sp500"]);
      benchRef.current = ["sp500"];
      setBenchBusy(true);
      load(range, { summary: false, detail: false });
    }
  }

  function toggleBench(id: string) {
    const next = bench.includes(id) ? bench.filter((b) => b !== id) : [...bench, id];
    setBench(next);            // zaznaczenie zmienia się NATYCHMIAST, nie po odpowiedzi
    benchRef.current = next;
    setBenchBusy(true);
    load(range, { summary: false, detail: false });
  }

  async function onPull() {
    setBusy(true);
    // `refresh()` to zapis (wymusza ponowne pobranie kursów), więc dla gościa
    // kończy się odmową 401 — a każda odmowa przy zapisie otwiera okno logowania.
    // Odświeżenie widoku nie może prosić o konto: gość ma prawo je odświeżyć.
    if (user) {
      try { await refresh(); } catch { /* i tak przeliczy się przy odczycie */ }
    }
    await load(range);
    setBusy(false);
  }

  const dayMap = useMemo(
    () => Object.fromEntries((day?.positions || []).map((p) => [p.ticker, p])),
    [day]);

  // w trybie „po kosztach" wszystkie kwoty sesji przesuwamy o ten sam koszt wyjścia
  const shift = net ? summary?.summary.exit_cost ?? 0 : 0;
  /* Przesunięta linia sesji liczona RAZ. Wersja `values.map(...)` w trakcie renderu
     dawała wykresowi za każdym razem nową tablicę — a więc pełne przeliczenie
     geometrii przy każdym ruchu myszy nad wykresem. */
  const dayValues = useMemo(
    () => (shift ? (day?.values || []).map((x) => x - shift) : day?.values || []),
    [day, shift]);

  if (loading) {
    return (
      <View style={s.center}>
        <ActivityIndicator color={C.green} size="large" />
        <Text style={s.dim}>Wczytuję portfel…</Text>
      </View>
    );
  }
  // Pierwsze ładowanie padło (najczęściej brak sieci albo serwer chwilowo nie
  // odpowiada). NIE pokazujemy tu gołego „Serwer odpowiedział 499" na cały ekran:
  // dla człowieka to ślepy komunikat, a dla robota Google — bo on wykonuje
  // JavaScript i renderuje TEN ekran — to jedyna treść, jaką widzi pod adresem
  // głównym, więc favicon i opis strony przegrywały z komunikatem o błędzie.
  // Zamiast tego dajemy markowy panel z opisem serwisu (ten sam dla wszystkich —
  // żadnego podstawiania treści pod wyszukiwarkę) i przycisk ponowienia.
  if (err && !series && !day) {
    return (
      <ScrollView contentContainerStyle={s.fallback} showsVerticalScrollIndicator={false}>
        <View style={s.brandRow}><BrandLogo width={152} /></View>
        <Text style={s.fbTitle}>Kalendarz wyników spółek i portfel inwestycyjny</Text>
        <Text style={s.fbDesc}>
          Kalendarz wyników spółek z GPW i giełd amerykańskich, prognozy analityków
          i śledzenie portfela inwestycyjnego. Po polsku, za darmo, w przeglądarce
          i na telefonie.
        </Text>
        <Text style={s.fbHint}>
          Nie udało się teraz połączyć z serwerem, żeby wczytać dane. Odśwież za chwilę —
          treść pojawi się automatycznie.
        </Text>
        <LiquidButton label="Spróbuj ponownie" full={false} style={{ minWidth: 220, marginTop: 4 }}
                      onPress={() => { setLoading(true); load(range); }} />
      </ScrollView>
    );
  }
  // Pusty portfel to nie stan błędu, tylko pierwszy krok: wgranie raportu musi być
  // pod ręką na pierwszym ekranie, bo bez niego apka nie ma czego pokazać.
  if (summary?.empty) {
    return (
      <ScrollView contentContainerStyle={{ paddingBottom: TAB_SPACE }}
                  showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
        <FadeIn>
          <View style={s.brandRow}><BrandLogo width={152} /></View>
          <ReportUpload onImported={() => { setLoading(true); load(range); }} />
        </FadeIn>
      </ScrollView>
    );
  }

  const m = summary!.summary;
  const dayOk = isDay && day && !day.empty;
  // nagłówek pokazuje zmianę z wybranego zakresu — dla 1D jest to ruch dzisiejszej sesji
  const chgPct = dayOk ? day!.stats.change_pct : series?.stats.change_pct ?? 0;
  const chgPln = dayOk ? day!.stats.change_pln
    : (net ? series?.stats.profit_net_pln : series?.stats.profit_pln) ?? 0;
  const up = chgPct >= 0;
  const rangeName = dayOk && !day!.is_today
    ? `sesja ${fmtDayLong(day!.session_date)}`
    : RANGES.find((r) => r.id === range)?.name;

  const sorted = [...summary!.positions].sort((a, b) => {
    if (isDay && (sort === "pl" || sort === "pct")) {
      const da = dayMap[a.ticker], db = dayMap[b.ticker];
      // pozycja przed sesją nie ma zmiany — zero to brak zdarzenia, a nie wynik,
      // więc nie może konkurować w rankingu ze spadkami. Ląduje pod listą.
      const ra = da?.traded ? 0 : da?.no_data ? 2 : 1;
      const rb = db?.traded ? 0 : db?.no_data ? 2 : 1;
      if (ra !== rb) return ra - rb;
      if (ra !== 0) return b.value_pln - a.value_pln;
      return sort === "pl"
        ? (db?.change_pln ?? 0) - (da?.change_pln ?? 0)
        : (db?.change_pct ?? 0) - (da?.change_pct ?? 0);
    }
    return sort === "value" ? b.value_pln - a.value_pln
      : sort === "pl" ? (net ? b.pl_net_pln - a.pl_net_pln : b.pl_pln - a.pl_pln)
      : sort === "pct" ? (net ? b.pl_net_pct - a.pl_net_pct : b.pl_pct - a.pl_pct)
      : a.ticker.localeCompare(b.ticker);
  });

  // wykres mieści się w kolumnie treści, nie w całym oknie: 18 px marginesu ekranu
  // i 14 px wyściółki karty z każdej strony
  const chartW = column - 36 - 28;
  const chartH = chartHeight(240, wide, chartW);
  // Szczegółowy przebieg rysujemy tylko wtedy, gdy naprawdę dotyczy WYBRANEGO zakresu
  // (po przełączeniu zakresu stara odpowiedź jeszcze przez chwilę siedzi w stanie)
  // i tylko poza porównaniem z rynkiem — tam potrzebna jest siatka dni pod benchmarki.
  const detail = !isDay && mode !== "compare" && hist && !hist.empty
    && hist.range === range && hist.ts.length > 1 ? hist : null;

  /** Wykres portfela — jeden kod na kartę i na pełny ekran, żeby nie rozjechały się
   *  ze sobą przy każdej zmianie. `zoomable` włącza przybliżanie i przesuwanie. */
  const renderChart = (w: number, h: number, zoomable = false) => {
    if (switching) {
      return (
        <View style={{ height: h + 26, alignItems: "center", justifyContent: "center" }}>
          <ActivityIndicator color={C.green} />
        </View>
      );
    }
    // dosypanie historii wołamy tylko poza sesją dnia: „1D" ma własne dane
    // śróddzienne jednej sesji i cofanie się w nich nie ma czego pokazać
    const needData = zoomable && !isDay
      ? (need: { side: "older" | "finer" }) => { if (need.side === "older") extendRange(); }
      : undefined;
    if (isDay) {
      return dayOk ? (
        // koszt wyjścia w ciągu sesji się nie zmienia, więc przesuwamy całą
        // linię o tę samą kwotę — kształt i zmiana dnia zostają nietknięte
        <PortfolioChart
          ts={day!.ts} values={dayValues}
          baseline={day!.base - shift}
          tzOffset={day!.tz_offset} mode="value" width={w} height={h} positive={up}
          zoomable={zoomable} resetKey={reset}
        />
      ) : (
        <View style={{ height: h + 26, alignItems: "center", justifyContent: "center" }}>
          <Text style={s.dim}>{day?.reason || "Brak notowań śróddziennych dla tej sesji"}</Text>
        </View>
      );
    }
    if (detail) {
      // ten sam zakres co wyżej, tylko rysowany ze słupków śróddziennych:
      // punkty istnieją wyłącznie tam, gdzie coś się notowało, więc noce
      // i weekendy nie rozciągają wykresu płaską linią
      return (
        <PortfolioChart
          ts={detail.ts} tzOffset={detail.tz_offset}
          values={net ? detail.values_net : detail.values}
          invested={detail.invested}
          flows={series?.flows}
          mode={mode} width={w} height={h} positive={up} zoomable={zoomable}
          resetKey={reset} onNeedData={needData}
        />
      );
    }
    return (
      <PortfolioChart
        dates={series!.dates}
        values={net ? series!.values_net : series!.values}
        invested={series!.invested}
        twr={series!.twr} bench={series!.bench} benchMeta={BENCH}
        flows={mode === "compare" ? undefined : series!.flows}
        mode={mode} width={w} height={h} positive={up} zoomable={zoomable}
        resetKey={reset} onNeedData={needData}
      />
    );
  };

  const modeBar = (
    <Segmented options={MODES} value={mode} liquid tone="green"
               onChange={(x) => pickMode(x as ChartMode)} />
  );
  const rangeBar = (
    <ScrollView horizontal showsHorizontalScrollIndicator={false}
                contentContainerStyle={s.ranges}>
      {RANGES.map((r) => (
        <MetalButton key={r.id} label={r.label} size="sm" tone="green" liquid
                     active={range === r.id} onPress={() => pickRange(r.id)} />
      ))}
    </ScrollView>
  );
  const benchBar = (
    <View style={s.benchRow}>
      {Object.entries(BENCH).map(([id, b]) => (
        <MetalButton key={id} label={b.label} size="sm" round accent={b.color}
                     active={bench.includes(id)} onPress={() => toggleBench(id)} />
      ))}
      {/* Zaznaczenie zmienia się od razu, ale linia na wykresie musi przyjść
          z serwera. Bez tego znaku jedyną informacją zwrotną było „nic się nie
          dzieje" — a to nie do odróżnienia od zepsutego przycisku. */}
      {benchBusy && <ActivityIndicator color={C.green} size="small" style={{ marginLeft: 2 }} />}
    </View>
  );

  return (
    <ScrollView
      contentContainerStyle={s.wrap}
      showsVerticalScrollIndicator={false}
      refreshControl={<RefreshControl refreshing={busy} onRefresh={onPull} tintColor={C.green} />}
    >
      <FadeIn>
        <View style={s.brandRow}>
          <BrandLogo width={152} />
          <View style={{ flex: 1 }} />
          <RefreshButton busy={busy} onPress={onPull} />
        </View>
        <View style={s.heroRow}>
          <Text style={s.label}>Wartość portfela</Text>
          <MetalButton label={net ? "po kosztach" : "brutto"} size="sm" tone="green" liquid
                       active={net} round onPress={toggleNet} />
        </View>
        <Text style={s.hero}>{fmtPLN(net ? m.value_net : m.value)}</Text>
        <View style={s.chipRow}>
          <View style={[s.chip, { backgroundColor: up ? C.greenDim : C.redDim }]}>
            <Text style={[s.chipTxt, { color: up ? C.green : C.red }]}>
              {fmtPct(chgPct)}   {sgnPLN(chgPln)}
            </Text>
          </View>
          <Text style={s.rangeName}>{rangeName}</Text>
        </View>
        {net && (
          <Text style={s.netNote}>
            po odjęciu kosztów wyjścia {fmtPLN(m.exit_cost)} · dotknij, aby zobaczyć brutto
          </Text>
        )}
        <LiveBar q={summary!.quotes} onPress={() => load(range)} />
      </FadeIn>

      {/* Gość ogląda konto pokazowe, więc saldo powyżej nie jest jego. Zaproszenie
          do wgrania własnego raportu musi stać dokładnie tutaj — pod tą kwotą,
          a nie dwie zakładki dalej w „Więcej", gdzie nikt go nie szuka. */}
      {!user && (
        <FadeIn delay={40}>
          <KontoPokazowe onImported={() => { setLoading(true); load(range); }} />
        </FadeIn>
      )}

      <FadeIn delay={90}>
        <Card style={{ marginTop: 18 }} padded={false}>
          {isDay ? (
            <View style={s.sessionBar}>
              <Text style={s.sessionTxt}>
                Sesja {day && !day.empty ? fmtDayLong(day.session_date) : "—"}
              </Text>
              {!!day && !day.empty && (
                <Text style={s.sessionMeta}>
                  <Text style={{ color: day.market_open ? C.green : C.dim }}>
                    {day.market_open ? "trwa" : "zamknięta"}
                  </Text>
                  {day.last_bar ? ` · notowania z ${fmtClock(day.last_bar, day.tz_offset)}` : ""}
                  {" "}· {day.traded}/{day.total} pozycji w ruchu
                  {day.stats.frozen_pln > 0
                    ? ` · ${fmtPLN0(day.stats.frozen_pln)} zł czeka na otwarcie`
                    : ""}
                </Text>
              )}
            </View>
          ) : (
            <View style={{ paddingHorizontal: 14, paddingTop: 14 }}>{modeBar}</View>
          )}

          <View style={{ padding: 14, paddingBottom: 6 }}>
            {renderChart(chartW, chartH)}
          </View>

          {!isDay && mode === "compare" && benchBar}

          {/* pasek zakresów, a na jego końcu lupa na pełny ekran — tak jak w apkach
              brokerskich: zakres i powiększenie leżą obok siebie */}
          <View style={s.rangeRow}>
            <View style={{ flex: 1 }}>{rangeBar}</View>
            <MetalButton label="⤢" size="sm" tone="green" round
                         onPress={() => setFullscreen(true)}
                         textStyle={{ fontSize: 15, lineHeight: 19 }}
                         style={{ marginRight: 10, marginBottom: 10 }} />
          </View>

          {!isDay && mode === "compare" && bench.length === 0 && (
            <Text style={s.benchHint}>
              Wybierz benchmark, żeby porównać swój wynik z rynkiem. Liczymy stopę zwrotu
              ważoną czasem — wpłaty nie zaburzają porównania.
            </Text>
          )}
        </Card>
      </FadeIn>

      <ChartFullscreen
        visible={fullscreen}
        onClose={() => setFullscreen(false)}
        title="Portfel"
        subtitle={`${fmtPLN(net ? m.value_net : m.value)} · ${fmtPct(chgPct)} ${rangeName || ""}`}
        hint="Przeciągnij, aby przesuwać · szczypnij albo kółko myszy, aby przybliżyć · dwa stuknięcia wracają do całości · przytrzymaj, aby odczytać wartość"
        controls={
          <>
            {!isDay && modeBar}
            {!isDay && mode === "compare" && benchBar}
            {rangeBar}
          </>
        }
      >
        {({ width: w, height: h }) => renderChart(w, h, true)}
      </ChartFullscreen>

      <FadeIn delay={150}>
        <View style={s.stats}>
          {dayOk ? (
            <>
              <Stat k="Zmiana dziś" v={sgnPLN(day!.stats.change_pln)}
                    s2={fmtPct(day!.stats.change_pct)} color={plColor(day!.stats.change_pln)} />
              <Stat k="Zakres sesji"
                    v={`${fmtPLN0(day!.stats.low - shift)} – ${fmtPLN0(day!.stats.high - shift)} zł`}
                    s2="najniżej – najwyżej" />
              <Stat k="Odniesienie" v={fmtPLN(day!.base - shift)}
                    s2="zamknięcie poprzedniej sesji" />
              <Stat k="Wpływ walut" v={sgnPLN(day!.stats.fx_change_pln)}
                    s2="z tego sam kurs do PLN" color={plColor(day!.stats.fx_change_pln)} />
            </>
          ) : (
            <>
              <Stat k="Wpłaty netto" v={fmtPLN(m.net_invested)}
                    s2={`${summary!.accounts.length} ${plural(summary!.accounts.length, "konto", "konta", "kont")}`} />
              <Stat k={net ? "Wynik po kosztach" : "Wynik"}
                    v={sgnPLN(net ? m.profit_net : m.profit)}
                    s2={net ? "wartość netto − wpłaty" : "wartość − wpłaty"}
                    color={plColor(net ? m.profit_net : m.profit)} />
              <Stat k="Stopa zwrotu" v={fmtPct(m.twr_total_pct)} s2="ważona czasem, brutto"
                    color={plColor(m.twr_total_pct)} />
              <Stat k="XIRR" v={m.xirr_pct == null ? "—" : fmtPct(m.xirr_pct)} s2="roczna, wg wpłat"
                    color={plColor(m.xirr_pct ?? 0)} />
              <Stat k="Koszt wyjścia" v={fmtPLN(m.exit_cost)}
                    s2="sprzedaż + zamiana na PLN" color={C.amber} />
              <Stat k="Zapłacone opłaty" v={fmtPLN(m.fees_paid)}
                    s2="spready i prowizje do dziś" />
            </>
          )}
        </View>
      </FadeIn>

      {/* Portfele i majątek. Sekcja SAMA decyduje, czy się pokazać: znika bez
          śladu, dopóki ktoś nie utworzy drugiego portfela albo nie dopisze
          czegoś, o czym broker nie wie. Kwota nad wykresem to nadal wyłącznie
          rachunek maklerski — majątek dokłada się dopiero tutaj. */}
      <WealthSection onZmiana={() => load(range)} />

      <View style={s.tabWrap}>
        <Segmented
          options={[{ id: "positions", label: "Pozycje" },
                    { id: "watch", label: "Obserwowane" }]}
          value={tab} liquid tone="green"
          onChange={(t) => pickTab(t as "positions" | "watch")}
        />
        <Text style={s.tabHint}>
          {tab === "positions"
            ? (isDay ? "Zmiana od zamknięcia poprzedniej sesji" : "Spółki, które masz w portfelu")
            : "Spółki z całego świata, które śledzisz"}
        </Text>
      </View>

      {tab === "watch" ? (
        <>
          <Watchlist items={watch} loading={watchBusy} onChanged={loadWatch}
                     onOpen={setOpenSymbol} />
          <BrandFooter />
          <CompanyScreen symbol={openSymbol} onClose={() => setOpenSymbol(null)}
                         onWatchChange={loadWatch} />
        </>
      ) : (
      <>
      <View style={s.sortRow}>
        {([["value", "wartość"],
           ["pl", isDay ? "zmiana" : "zysk"],
           ["pct", isDay ? "zmiana %" : "zysk %"],
           ["name", "nazwa"]] as const)
          .map(([k, lbl]) => (
            <MetalButton key={k} label={lbl} size="sm" tone="green" round liquid
                         active={sort === k} onPress={() => setSort(k as SortKey)} />
          ))}
      </View>

      {sorted.map((p, i) => {
        // w trybie 1D pokazujemy ruch dnia; pozycja, która dziś nie handlowała, ma
        // dokładnie zero — jej notowanie przedsesyjne idzie osobno, w linijce opisu
        const d = isDay ? dayMap[p.ticker] : undefined;
        const showDay = isDay;
        // ruch dnia zostaje brutto — koszty nie zmieniają się w ciągu sesji,
        // więc odejmowanie ich od dziennej zmiany tylko zaciemniałoby obraz
        const plnChange = showDay ? d?.change_pln ?? 0 : net ? p.pl_net_pln : p.pl_pln;
        const pctChange = showDay ? d?.change_pct ?? 0 : net ? p.pl_net_pct : p.pl_pct;
        const idle = showDay && (!d || d.no_data ? "brak danych"
          : d.traded ? "" : d.ext_phase === "post" ? "po sesji" : "przed sesją");
        return (
          <FadeIn key={p.ticker} delay={Math.min(i * 22, 260)} offset={10}>
            <Press onPress={() => setOpenSymbol(p.ticker)} scaleTo={0.985}>
            <Card style={s.posCard}>
              <Logo ticker={p.ticker} />
              <View style={{ flex: 1, marginLeft: 12 }}>
                <Text style={s.posTicker}>{p.ticker}</Text>
                {/* status sesji ląduje w wolnym miejscu obok nazwy — w linijce niżej
                    nie mieścił się na telefonie i ucinał wartość notowania */}
                <View style={s.posNameRow}>
                  <Text style={s.posName} numberOfLines={1}>{p.name}</Text>
                  {!!idle && (
                    <View style={s.idleTag}>
                      <Text style={s.posIdle}>{idle}</Text>
                      {showDay && d?.ext_pct != null && (
                        <Text style={[s.posExt, { color: plColor(d.ext_pct) }]}>
                          {" "}{fmtPct(d.ext_pct)}
                        </Text>
                      )}
                    </View>
                  )}
                </View>
                <Text style={s.posMeta} numberOfLines={1}>
                  {p.shares.toLocaleString("pl-PL", { maximumFractionDigits: 4 })} szt ·
                  {" "}{p.price.toLocaleString("pl-PL", { maximumFractionDigits: 2 })} {p.currency}
                  {net && p.exit_cost_pln > 0 && (
                    <Text style={s.posCost}>  · wyjście {fmtPLN(p.exit_cost_pln)}</Text>
                  )}
                </Text>
              </View>
              <View style={{ alignItems: "flex-end" }}>
                <Text style={s.posValue}>{fmtPLN(net ? p.value_net_pln : p.value_pln)}</Text>
                <Text style={[s.posPl, { color: plColor(plnChange) }]}>{sgnPLN(plnChange)}</Text>
                <View style={[s.pctPill,
                              { backgroundColor: pctChange >= 0 ? C.greenDim : C.redDim },
                              !!idle && { opacity: 0.5 }]}>
                  <Text style={[s.pctTxt, { color: plColor(pctChange) }]}>{fmtPct(pctChange)}</Text>
                </View>
              </View>
            </Card>
            </Press>
          </FadeIn>
        );
      })}

      <BrandFooter note={isDay
        ? "notowania co 5 minut · dotknij pozycji, aby zobaczyć szczegóły spółki"
        : `wycena z ${summary!.computed_at?.slice(0, 10)} · dotknij pozycji, aby zobaczyć szczegóły`} />

      <CompanyScreen symbol={openSymbol} onClose={() => setOpenSymbol(null)}
                     onWatchChange={loadWatch} />
      </>
      )}
    </ScrollView>
  );
}

function Stat({ k, v, s2, color }: { k: string; v: string; s2: string; color?: string }) {
  return (
    <View style={s.stat}>
      <Text style={s.statK}>{k}</Text>
      <Text style={[s.statV, color ? { color } : null]} numberOfLines={1} adjustsFontSizeToFit>
        {v}
      </Text>
      <Text style={s.statS} numberOfLines={1}>{s2}</Text>
    </View>
  );
}

/** Zaproszenie dla gościa: to konto jest pokazowe, tu wgrywasz swoje.
 *
 *  Zwinięte do jednego paska, bo stoi nad wykresem — rozwinięty formularz spychałby
 *  cały ekran w dół każdemu, kto tylko ogląda. Rozwija się dotknięciem i wtedy
 *  dostaje pełne wgrywanie razem ze znakiem zapytania do samouczka.
 */
function KontoPokazowe({ onImported }: { onImported: () => void }) {
  const [open, setOpen] = useState(false);

  return (
    <View style={s.demo}>
      <Press onPress={() => setOpen((v) => !v)} scaleTo={0.99}>
        <View style={s.demoRzad}>
          <View style={s.demoIkona}><Text style={s.demoIkonaTxt}>▲</Text></View>
          <View style={{ flex: 1 }}>
            <Text style={s.demoTytul}>To jest portfel pokazowy</Text>
            <Text style={s.demoOpis}>
              Powyższa kwota nie jest Twoja. Wgraj raport z XTB, a zobaczysz tu własne liczby.
            </Text>
          </View>
          <Text style={s.demoZnak}>{open ? "−" : "+"}</Text>
        </View>
      </Press>

      {open && <ReportUpload compact onImported={onImported} />}
    </View>
  );
}

