/** Wykres na cały ekran — to samo, co w karcie, tylko duże i do oglądania.
 *
 *  Okno bierze CAŁE dostępne miejsce: na telefonie jest to pełny ekran, na komputerze
 *  całe okno przeglądarki.
 *
 *  Rozmiar wykresu liczymy z wymiarów okna, a nie mierzymy przez `onLayout`. Pomiar
 *  bywa zawodny: w oknie modalnym potrafi zwrócić zero i wtedy wykres w ogóle się nie
 *  rysuje (dokładnie to się tu działo). Wysokość pasków sterowania mierzymy, ale
 *  z sensowną wartością domyślną — gdy pomiar nie dojdzie, wykres i tak ma rozsądny
 *  rozmiar, a przy zmianie rozmiaru okna na komputerze przelicza się sam.
 *
 *  Sterowanie (zakresy, tryby, benchmarki) wstrzykuje ekran wywołujący — dzięki temu
 *  klikanie w pełnym ekranie działa na tym samym stanie co pod spodem i po zamknięciu
 *  nic się nie rozjeżdża.
 */
import React, { useState } from "react";
import {
  Modal, Platform, SafeAreaView, ScrollView, StatusBar, StyleSheet, Text,
  useWindowDimensions, View,
} from "react-native";
import { HEADER_H } from "./PortfolioChart";
import { C, T } from "../theme";
import { MetalButton } from "../ui";

type Size = { width: number; height: number };

/** Wysokości stałych części okna — nagłówek, podpowiedź, pasek nad wykresem.
 *  Ten ostatni bierzemy wprost z wykresu, żeby nie rozjechał się przy zmianach. */
const HEAD_H = 56;
const HINT_H = 30;
const LEGEND_H = HEADER_H;

export default function ChartFullscreen({
  visible, onClose, title, subtitle, controls, hint, children,
}: {
  visible: boolean;
  onClose: () => void;
  title: string;
  subtitle?: string;
  /** paski wyboru: tryb wykresu, zakres czasu, benchmarki */
  controls?: React.ReactNode;
  /** krótka podpowiedź pod wykresem — jak się nim posługiwać */
  hint?: string;
  children: (size: Size) => React.ReactNode;
}) {
  const win = useWindowDimensions();
  const [ctrlH, setCtrlH] = useState(controls ? 120 : 0);

  const top = Platform.OS === "android" ? (StatusBar.currentHeight || 0) : 0;
  const size: Size = {
    width: Math.max(240, Math.round(win.width) - 16),
    height: Math.max(180, Math.round(win.height) - top - HEAD_H
                          - (hint ? HINT_H : 0) - LEGEND_H - ctrlH - 24),
  };

  return (
    /* Bez animacji wejścia. W przeglądarce okno modalne jest w trakcie przejścia
       „przezroczyste dla kliknięć", a stan wraca do normy dopiero po zakończeniu
       animacji — gdy karta przeglądarki akurat nie rysuje klatek, to zakończenie
       nie przychodzi i całe okno zostaje nieklikalne. Wykres i tak ma pojawić się
       natychmiast, więc nic na tym nie tracimy. */
    <Modal visible={visible} animationType="none" onRequestClose={onClose}
           transparent={false} supportedOrientations={["portrait", "landscape"]}>
      <SafeAreaView style={[s.root, { paddingTop: top }]}>
        <StatusBar barStyle="light-content" />
        <View style={s.bar}>
          <View style={{ flex: 1 }}>
            <Text style={s.title} numberOfLines={1}>{title}</Text>
            {!!subtitle && <Text style={s.sub} numberOfLines={1}>{subtitle}</Text>}
          </View>
          <MetalButton label="Zamknij" size="sm" onPress={onClose} />
        </View>

        <View style={s.plot}>{children(size)}</View>

        {!!hint && <Text style={s.hint}>{hint}</Text>}

        {!!controls && (
          <ScrollView
            style={s.ctrlWrap} contentContainerStyle={s.ctrl}
            showsVerticalScrollIndicator={false}
            onLayout={(e) => {
              const h = Math.round(e.nativeEvent.layout.height);
              if (h > 0 && Math.abs(h - ctrlH) > 4) setCtrlH(Math.min(180, h));
            }}
          >
            {controls}
          </ScrollView>
        )}
      </SafeAreaView>
    </Modal>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg },
  bar: {
    flexDirection: "row", alignItems: "center", gap: 12, height: HEAD_H,
    paddingHorizontal: 14,
  },
  title: { ...T.h2, color: C.text },
  sub: { color: C.muted, fontSize: 11.5, marginTop: 1 },

  plot: { flex: 1, paddingHorizontal: 8, justifyContent: "center" },
  hint: {
    color: C.dim, fontSize: 11, textAlign: "center", height: HINT_H,
    paddingHorizontal: 16, paddingTop: 2,
  },

  ctrlWrap: { maxHeight: 180, flexGrow: 0 },
  ctrl: { paddingHorizontal: 12, paddingTop: 8, paddingBottom: 12, gap: 10 },
});
