import { StatusBar } from "expo-status-bar";
import React, { useEffect, useState } from "react";
import { ActivityIndicator, Platform, Pressable, SafeAreaView, StyleSheet, Text, View } from "react-native";
import { getConfig, getPref, loadConfig, odswiezMojeSpolki, setPref } from "./src/api";
import { AuthProvider, useAuth } from "./src/auth/AuthContext";
import { AppBackground, BG_PREF, DEFAULT_BG } from "./src/backgrounds";
import { BrandLogo } from "./src/components/Brand";
import CookieNotice from "./src/components/CookieNotice";
import EmailConsent from "./src/components/EmailConsent";
import PushPrompt from "./src/components/PushPrompt";
import TabBar, { TabId } from "./src/components/TabBar";
import { openCompany, setCompanyOpener } from "./src/companyRouter";
import * as powiadomienia from "./src/notifications";
import { setTabOpener } from "./src/tabRouter";
import AllocationScreen from "./src/screens/AllocationScreen";
import AppPromoScreen from "./src/screens/AppPromoScreen";
import AuthScreen from "./src/screens/AuthScreen";
import CompanyScreen from "./src/screens/CompanyScreen";
import ConnectScreen from "./src/screens/ConnectScreen";
import HistoryScreen from "./src/screens/HistoryScreen";
import HubScreen, { HubSection } from "./src/screens/HubScreen";
import { COLUMN_MAX, TABBAR_GAP, useLayout } from "./src/layout";
import MoreScreen from "./src/screens/MoreScreen";
import OverviewScreen from "./src/screens/OverviewScreen";
import PagesScreen from "./src/screens/PagesScreen";
import PaywallScreen from "./src/screens/PaywallScreen";
import PremiumScreen from "./src/screens/PremiumScreen";
import ToolsScreen from "./src/screens/ToolsScreen";
import { C } from "./src/theme";
import { ErrorBoundary } from "./src/ui";
import { nasluchujCofania, ustawAdres, widokZAdresu } from "./src/webRoutes";

const HUB_PREF = "hub.section";

/** Konto i premium obejmują całą aplikację, więc dostawca stoi najwyżej — dzięki temu
 *  kłódka na dowolnym ekranie umie sama otworzyć stronę sprzedażową. */
export default function App() {
  return (
    <AuthProvider>
      <Shell />
    </AuthProvider>
  );
}

/** Okna konta i strony sprzedażowej leżą nad wszystkim, niezależnie od zakładki. */
function AccountLayer() {
  const { paywall, hidePaywall, loginOpen, openLogin, closeLogin,
          me, ready: kontoGotowe } = useAuth();
  // Jedno okno spółki na cały program: skład funduszu w Skanerze ETF też z niego
  // korzysta, a trzymanie go tutaj zamiast w każdym ekranie z osobna oszczędza
  // zagnieżdżania modali i cyklicznych importów.
  const [company, setCompany] = useState<string | null>(null);
  // „&obserwuj=1" z podstrony pozycjonowanej: karta ma nie tylko się otworzyć,
  // ale też dopisać spółkę do obserwowanych — bo taka była treść przycisku.
  const [obserwuj, setObserwuj] = useState(false);

  useEffect(() => {
    setCompanyOpener(setCompany);
    // Wejście z podstrony pozycjonowanej: adres „/?spolka=CDR.WA" otwiera od razu
    // kartę tej spółki. Bez tego ktoś, kto przyszedł z Google na stronę wyników
    // CD Projektu i kliknął „Otwórz w aplikacji", lądował na ekranie startowym
    // i musiał wyszukać spółkę jeszcze raz — czyli tracił wątek dokładnie
    // w chwili największego zainteresowania.
    //
    // Blok dotyczy WYŁĄCZNIE przeglądarki: na telefonie `Platform.OS` to „ios"
    // albo „android", więc nic się tu nie wykonuje i `window` nie jest dotykane.
    if (Platform.OS === "web") {
      try {
        const adres = new URLSearchParams(window.location.search);
        const symbol = adres.get("spolka");
        if (symbol && symbol.trim()) {
          setCompany(symbol.trim().toUpperCase());
          if (adres.get("obserwuj") === "1") setObserwuj(true);
        }
      } catch {
        // Zły adres nie może zablokować startu aplikacji — po prostu nic nie otwieramy.
      }
    }
    return () => setCompanyOpener(null);
  }, []);

  /* Lista obserwowanych jest przypisana do konta, więc bez zalogowania dodanie
     nie ma prawa się udać. Czekamy na `ready` — stan konta wczytuje się po
     starcie i sprawdzony za wcześnie wyglądałby jak wylogowanie, otwierając
     okno logowania komuś, kto jest zalogowany. */
  useEffect(() => {
    if (obserwuj && kontoGotowe && !me) openLogin();
  }, [obserwuj, kontoGotowe, me]);

  return (
    <>
      {paywall !== null && (
        <PaywallScreen
          featureId={paywall}
          onClose={hidePaywall}
          onLogin={() => { hidePaywall(); openLogin(); }}
        />
      )}
      {loginOpen && <AuthScreen onClose={closeLogin} />}
      {company && (
        <CompanyScreen
          symbol={company}
          obserwujOdRazu={obserwuj}
          onClose={() => { setCompany(null); setObserwuj(false); }}
        />
      )}
    </>
  );
}

function Shell() {
  const { wide } = useLayout();
  const { ready: kontoGotowe, user } = useAuth();
  // Panel dewelopera nie ma już własnej zakładki — rozwija się w „Więcej", żeby
  // nie zajmować miejsca w pasku. Widzi go tylko właściciel (patrz `MoreScreen`),
  // a i tak o dostępie decydują endpointy (`require_owner`), nie interfejs.
  const [ready, setReady] = useState(false);
  const [tab, setTab] = useState<TabId>("overview");
  // Ekran połączenia z własnym serwerem — już nie brama wejściowa, tylko okno
  // wywoływane z „Więcej". Potrzebny właścicielowi, gdy pracuje na komputerze.
  const [connectOpen, setConnectOpen] = useState(false);
  const [bg, setBg] = useState(DEFAULT_BG);
  // Bot i Earnings dzielą jedną zakładkę; domyślnie otwiera się kalendarz wyników
  const [hub, setHub] = useState<HubSection>("earnings");

  useEffect(() => {
    // Adres serwera jest znany od startu (produkcyjny albo własny, zapisany
    // wcześniej), więc nie ma już czego pytać przed wejściem do aplikacji.
    loadConfig().then(() => setReady(true));
    getPref(BG_PREF, DEFAULT_BG).then(setBg);
    // Zapamiętana sekcja ustawia się TYLKO wtedy, gdy adres nie mówi czego innego —
    // inaczej wejście na „/bot-newsow" przestawiałoby się z powrotem na Earnings
    // w chwili, gdy odczyt z pamięci dobiegnie końca.
    getPref(HUB_PREF, "earnings").then((v) => {
      if (!widokZAdresu()?.hub) setHub(v as HubSection);
    });

    // Adres decyduje o tym, co widać na starcie: wejście na „/alokacja" albo
    // odświeżenie strony pod tym adresem otwiera właściwą zakładkę.
    const zAdresu = widokZAdresu();
    if (zAdresu) {
      setTab(zAdresu.tab);
      if (zAdresu.hub) setHub(zAdresu.hub);
    }
    // Skrót „Bot newsów" w Narzędziach przełącza zakładkę przez ten rejestr —
    // dzięki temu ekran narzędzi nie musi nic wiedzieć o powłoce aplikacji.
    setTabOpener((t, h) => {
      setTab(t as TabId);
      if (h) { setHub(h as HubSection); setPref(HUB_PREF, h); }
      ustawAdres({ tab: t as TabId, hub: (h as HubSection) || undefined });
    });

    // Kanał powiadomień Androida musi istnieć ZANIM przyjdzie pierwsze
    // powiadomienie, więc zakładamy go przy starcie. Na webie ta funkcja nic
    // nie robi — moduł natywny tam nie istnieje (patrz `src/notifications.ts`).
    powiadomienia.przygotuj();

    // Dotknięcie powiadomienia ma prowadzić TAM, gdzie jest jego treść: przy
    // newsie do karty spółki, przy wynikach do kalendarza. Powiadomienie, które
    // otwiera ekran startowy, każe szukać jeszcze raz tego, co się właśnie
    // przeczytało.
    const odepnijPush = powiadomienia.przyKlikniecu((dane) => {
      powiadomienia.wyczyscOdznake();
      if (dane?.kind === "news" && dane?.symbol) {
        setTab("bot");
        setHub("bot");
        openCompany(String(dane.symbol));
        return;
      }
      setTab("bot");
      setHub(dane?.kind === "news" ? "bot" : "earnings");
    });

    // Strzałka „wstecz" ma cofać o zakładkę, a nie zamykać całą aplikację.
    const odepnijCofanie = nasluchujCofania((w) => {
      setTab(w.tab);
      if (w.hub) setHub(w.hub);
    });

    return () => { odepnijPush(); odepnijCofanie(); setTabOpener(null); };
  }, []);

  /* Lista „moich spółek" po stronie serwera to cache, z którego silnik powiadomień
     korzysta zamiast przeliczać portfele przy każdym newsie. Odświeżamy ją raz na
     uruchomienie, a NIE przy wejściu na ekran bota — inaczej ktoś, kto zagląda
     tylko do kalendarza wyników, nigdy nie dostałby przypomnienia o publikacji
     wyników własnej spółki, bo serwer nie wiedziałby, że ją ma.

     Cicho i w tle: to sprzątanie, a nie coś, na co warto czekać. */
  useEffect(() => {
    if (!kontoGotowe || !user) return;
    odswiezMojeSpolki().catch(() => { /* spróbujemy przy następnym uruchomieniu */ });
  }, [kontoGotowe, user?.id]);

  /** Zmiana zakładki razem z adresem w pasku przeglądarki. */
  function pickTab(t: TabId) {
    setTab(t);
    ustawAdres({ tab: t, hub });
  }

  function pickHub(s: HubSection) {
    setHub(s);
    setPref(HUB_PREF, s);
    ustawAdres({ tab: "bot", hub: s });
  }

  function pickBg(id: string) {
    setBg(id);
    setPref(BG_PREF, id);
  }

  if (!ready) {
    return (
      <SafeAreaView style={s.root}>
        <StatusBar style="light" />
        <View style={s.center}>
          <BrandLogo width={190} style={{ marginBottom: 24 }} />
          <ActivityIndicator color={C.green} size="large" />
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={s.root}>
      <StatusBar style="light" />
      {/* wybrane tło rysuje się pod wszystkim; ekrany są przezroczyste */}
      <AppBackground id={bg} />
      {/* Na komputerze zakładki stoją pionowo przy lewej krawędzi, a treść zajmuje
          resztę; na telefonie zostaje kolejność pionowa z paskiem na dole. */}
      <View style={{ flex: 1, flexDirection: wide ? "row" : "column" }}>
        {wide && (
          <TabBar vertical active={tab} onChange={pickTab}
                  labels={{ bot: hub === "bot" ? "Bot newsów" : "Earnings" }} />
        )}
        <View style={{ flex: 1 }}>
          <View style={{ flex: 1 }}>
            {/* Ekrany trzymamy zamontowane — przełączanie zakładek jest wtedy natychmiastowe,
                bez ponownego pobierania danych przy każdym powrocie. */}
            <Pane visible={tab === "overview"} name="Przegląd" wide={wide}><OverviewScreen /></Pane>
            <Pane visible={tab === "allocation"} name="Alokacja" wide={wide}><AllocationScreen /></Pane>
            <Pane visible={tab === "history"} name="Zamknięte" wide={wide}><HistoryScreen /></Pane>
            <Pane visible={tab === "bot"} name={hub === "bot" ? "Bot newsów" : "Earnings"} wide={wide}>
              <HubScreen section={hub} onSection={pickHub} visible={tab === "bot"} />
            </Pane>
            <Pane visible={tab === "tools"} name="Narzędzia" wide={wide}><ToolsScreen /></Pane>
            <Pane visible={tab === "premium"} name="Premium" wide={wide}><PremiumScreen /></Pane>
            <Pane visible={tab === "more"} name="Więcej" wide={wide}>
              <MoreScreen onDisconnect={() => setConnectOpen(true)} visible={tab === "more"}
                          background={bg} onBackground={pickBg} />
            </Pane>
            {/* Dwie zakładki tylko dla przeglądarki. Warunek jest tu, a nie tylko
                w pasku zakładek, żeby na telefonie te ekrany nie trafiły nawet do
                paczki wykonywanej przy starcie — na telefon nie ma po co wozić
                spisu stron pozycjonowanych ani zaproszenia do pobrania apki. */}
            {Platform.OS === "web" && (
              <>
                <Pane visible={tab === "pages"} name="Artykuły" wide={wide}><PagesScreen /></Pane>
                <Pane visible={tab === "app"} name="Aplikacja" wide={wide}><AppPromoScreen /></Pane>
              </>
            )}
            {/* Wyspa z zakładkami unosi się NAD treścią, przy dolnej krawędzi
                obszaru ekranów — dzięki temu przewijana zawartość idzie pod nią
                i widać, że ekran się nie kończy. Miejsce na ostatni wiersz dają
                ekrany, dokładając `TAB_SPACE` do dolnego marginesu.
                Listwy poniżej (dane pokazowe, ciasteczka) zostają w układzie,
                więc wyspa siada nad nimi, a nie na nich. */}
            {!wide && (
              <View style={s.tabFloat} pointerEvents="box-none">
                <TabBar active={tab} onChange={pickTab}
                        labels={{ bot: hub === "bot" ? "Bot newsów" : "Earnings" }} />
              </View>
            )}
          </View>
          <DemoBar />
          {/* tylko na stronie; na telefonie ten komponent zwraca null i nic nie kosztuje */}
          <CookieNotice />
        </View>
      </View>
      {connectOpen && (
        <View style={StyleSheet.absoluteFill}>
          <SafeAreaView style={s.root}>
            <ConnectScreen
              initialUrl={getConfig().baseUrl}
              initialToken={getConfig().token}
              onConnected={() => { setConnectOpen(false); setTab("overview"); }}
            />
          </SafeAreaView>
        </View>
      )}
      <AccountLayer />
      {/* Zgoda na powiadomienia — przy starcie; przy okazji odświeża token
          urządzenia, gdy zgoda już jest. */}
      <PushPrompt />
      {/* Pytanie o zgodę na e-mail — raz na konto, po zalogowaniu. */}
      <EmailConsent />
    </SafeAreaView>
  );
}

/** Pasek nad zakładkami: mówi wprost, że gość ogląda cudzy, przykładowy portfel.
 *
 *  Bez tego dane pokazowe byłyby nieuczciwe — ktoś mógłby wziąć je za własne albo
 *  za realny wynik aplikacji. Pasek znika w chwili zalogowania.
 */
function DemoBar() {
  const { user, openLogin } = useAuth();
  if (user) return null;
  return (
    <View style={s.demo}>
      <Text style={s.demoText}>
        <Text style={s.demoStrong}>Dane pokazowe. </Text>
        Oglądasz przykładowy portfel — tak wygląda Portevo z wgranym raportem.
      </Text>
      <Pressable onPress={openLogin} style={s.demoBtn}>
        <Text style={s.demoBtnText}>Zaloguj się</Text>
      </Pressable>
    </View>
  );
}

/** Kontener zakładki — montuje ekran dopiero przy pierwszym wejściu i potem go zachowuje.
 *
 *  Każda zakładka ma własny bezpiecznik: awaria jednej nie gasi pozostałych ani
 *  dolnego paska, więc zawsze da się przejść gdzie indziej i wrócić.
 */
function Pane({
  visible, name, wide, children,
}: { visible: boolean; name?: string; wide?: boolean; children: React.ReactNode }) {
  const [everShown, setEverShown] = useState(visible);
  useEffect(() => { if (visible) setEverShown(true); }, [visible]);
  if (!everShown) return null;
  return (
    <View style={[StyleSheet.absoluteFill, !visible && s.hidden]} pointerEvents={visible ? "auto" : "none"}>
      {/* Na szerokim ekranie treść zostaje w kolumnie pośrodku. Ekran zbudowany pod
          telefon, rozciągnięty na cały monitor, ma wiersze długości linijki — czyta
          się je fatalnie, a wykres robi się płaską kreską. */}
      <View style={wide ? s.column : { flex: 1 }}>
        <ErrorBoundary name={name}>{children}</ErrorBoundary>
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg },
  tabFloat: {
    position: "absolute", left: 0, right: 0, bottom: 0,
    paddingHorizontal: TABBAR_GAP, paddingBottom: TABBAR_GAP,
  },
  center: { flex: 1, alignItems: "center", justifyContent: "center" },
  hidden: { opacity: 0, zIndex: -1 },
  column: { flex: 1, width: "100%", maxWidth: COLUMN_MAX, alignSelf: "center" },
  demo: {
    flexDirection: "row", alignItems: "center", gap: 10,
    paddingHorizontal: 14, paddingVertical: 9,
    backgroundColor: "rgba(47,212,138,0.10)",
    borderTopWidth: 1, borderTopColor: "rgba(47,212,138,0.28)",
  },
  demoText: { flex: 1, color: C.text, fontSize: 12, lineHeight: 16.5 },
  demoStrong: { fontWeight: "700", color: C.green },
  demoBtn: {
    paddingHorizontal: 13, paddingVertical: 7, borderRadius: 9,
    backgroundColor: C.green,
  },
  demoBtnText: { color: "#08130d", fontSize: 12, fontWeight: "700" },
});
