/** Konto Supabase w aplikacji — logowanie e-mailem i przez Google.
 *
 *  Rozmawiamy z GoTrue (API uwierzytelniania Supabase) wprost przez `fetch`, bez
 *  `@supabase/supabase-js`. Powód jest praktyczny: projekt stoi na SDK 54 pod Expo Go,
 *  a każda dodatkowa paczka to kolejna rzecz, która może wymusić podniesienie wersji
 *  Expo. Potrzebujemy z całej biblioteki czterech wywołań HTTP — tyle się mieści tutaj.
 *
 *  Sesja leży w AsyncStorage. Token dostępowy żyje godzinę; odświeżamy go sami,
 *  z minutowym zapasem, przy każdym pobraniu.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Linking, Platform } from "react-native";
import * as WebBrowser from "expo-web-browser";

const K_SESSION = "portfel.supabase.session";
/** Ostatnio znany profil. Trzymamy go obok sesji, żeby zimny start bez zasięgu
 *  nie wyglądał jak wylogowanie — patrz `restore`. */
const K_USER = "portfel.supabase.user";
/** Ślad po świadomym wylogowaniu — patrz `signInGoogle`. */
const K_PICK = "portfel.pickAccount";

export const SUPABASE_URL = (process.env.EXPO_PUBLIC_SUPABASE_URL || "").replace(/\/+$/, "");
export const SUPABASE_ANON = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || "";

/** Czy w ogóle da się zalogować. Bez kluczy aplikacja działa jak dotąd — na tokenie panelu. */
export const authConfigured = () => Boolean(SUPABASE_URL && SUPABASE_ANON);

export type AuthUser = {
  id: string;
  email: string;
  name: string;
  avatar: string;
  provider: string;
};

type Session = { access_token: string; refresh_token: string; expires_at: number };

let session: Session | null = null;
let user: AuthUser | null = null;

/* ------------------------------------------------------------------ pomocnicze */

function toUser(u: any): AuthUser | null {
  if (!u?.id) return null;
  const meta = u.user_metadata || {};
  return {
    id: u.id,
    email: u.email || "",
    name: meta.full_name || meta.name || "",
    avatar: meta.avatar_url || "",
    provider: u.app_metadata?.provider || "email",
  };
}

/** Błąd z odpowiedzi GoTrue — niesie kod HTTP, bo od niego zależy, czy sesja
 *  jest do wyrzucenia (400/401 = serwer ją odrzucił), czy tylko nie doszliśmy
 *  (brak sieci = zostawiamy wszystko i próbujemy później). */
class AuthError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.status = status;
  }
}

async function gotrue(path: string, body?: any, token?: string) {
  if (!authConfigured()) throw new Error("Logowanie nie jest skonfigurowane w tej wersji aplikacji");
  const r = await fetch(`${SUPABASE_URL}/auth/v1${path}`, {
    method: body === undefined ? "GET" : "POST",
    headers: {
      apikey: SUPABASE_ANON,
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const js = await r.json().catch(() => ({}));
  if (!r.ok) throw new AuthError(pl(js), r.status);
  return js;
}

/** Komunikaty GoTrue są po angielsku — te najczęstsze tłumaczymy, resztę puszczamy dalej. */
function pl(js: any): string {
  const raw = String(js?.error_description || js?.msg || js?.error || js?.message || "");
  const map: Record<string, string> = {
    "Invalid login credentials": "Błędny adres e-mail albo hasło",
    "Email not confirmed": "Potwierdź adres e-mail — link czeka w skrzynce",
    "User already registered": "Konto z tym adresem już istnieje — zaloguj się",
    "Password should be at least 6 characters":
      "Hasło musi mieć co najmniej 6 znaków",
    "Unable to validate email address: invalid format": "To nie wygląda na adres e-mail",
  };
  return map[raw] || raw || "Nie udało się zalogować";
}

async function store(s: Session | null) {
  session = s;
  if (s) await AsyncStorage.setItem(K_SESSION, JSON.stringify(s));
  else await AsyncStorage.removeItem(K_SESSION);
}

/** Zapamiętuje profil obok sesji. Nie przerywamy niczego, gdy zapis się nie uda —
 *  to tylko wygoda przy starcie, a nie źródło prawdy o zalogowaniu. */
async function storeUser(u: AuthUser | null) {
  user = u;
  try {
    if (u) await AsyncStorage.setItem(K_USER, JSON.stringify(u));
    else await AsyncStorage.removeItem(K_USER);
  } catch { /* pamięć podręczna profilu jest opcjonalna */ }
}

async function cachedUser(): Promise<AuthUser | null> {
  try {
    const raw = await AsyncStorage.getItem(K_USER);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

/** Zapisuje sesję z odpowiedzi GoTrue.
 *
 *  `await` przy zapisie jest istotny: przy odświeżaniu dostajemy NOWY refresh
 *  token, a stary Supabase natychmiast unieważnia. Gdyby aplikację zamknięto
 *  między odebraniem a zapisem, na dysku zostałby token już nieważny — czyli
 *  wylogowanie przy następnym uruchomieniu.
 */
async function adopt(js: any): Promise<AuthUser | null> {
  if (!js?.access_token) return null;
  await store({
    access_token: js.access_token,
    // przy odświeżeniu Supabase zwraca nowy refresh token; gdyby go nie było,
    // trzymamy się poprzedniego zamiast zapisywać pustkę
    refresh_token: js.refresh_token || session?.refresh_token || "",
    // zapisujemy MOMENT wygaśnięcia — po restarcie aplikacji „3600 sekund" nic nie znaczy
    expires_at: Math.floor(Date.now() / 1000) + (js.expires_in || 3600),
  });
  if (js.user) await storeUser(toUser(js.user));
  return user;
}

/* ------------------------------------------------------------------- publiczne */

export function currentUser() {
  return user;
}

/** Wczytuje sesję z pamięci telefonu przy starcie aplikacji.
 *
 *  Gdy Supabase akurat nie odpowiada (brak zasięgu, uśpiony serwer), oddajemy
 *  ZAPAMIĘTANY profil zamiast `null`. Wcześniej każde takie potknięcie wyglądało
 *  na wylogowanie: ekran wracał do „zaloguj się", mimo że sesja spokojnie leżała
 *  na dysku i była ważna. Konto znika dopiero wtedy, gdy serwer je odrzuci
 *  (patrz `odswiez`) albo gdy użytkownik sam się wyloguje.
 */
/** Odczyt sesji z pamięci telefonu — RAZ, od razu przy starcie modułu.
 *
 *  Przez to portfel ładował się dwa razy: najpierw pokazowy, a właściwy dopiero
 *  po 30 sekundach. Ekran portfela pyta serwer w chwili zamontowania, a sesja
 *  była wczytywana dopiero w `restore()`, które rusza później (po sprawdzeniu
 *  linku startowego). Pierwsze żądanie wychodziło więc BEZ tokenu, serwer
 *  uznawał je za gościa i oddawał konto pokazowe — a pierwsze ustalenie konta
 *  celowo nie przeładowuje ekranów, więc własne dane przychodziły dopiero
 *  z cyklicznym odświeżeniem.
 *
 *  Teraz odczyt startuje przy imporcie, a `accessToken()` na niego czeka. Czeka
 *  wyłącznie na pamięć telefonu (milisekundy), nie na sieć — sprawdzenie konta
 *  u Supabase dalej dzieje się w tle, w `restore()`.
 */
let sesjaWczytana: Promise<void> | null = null;

function wczytajSesje(): Promise<void> {
  if (!sesjaWczytana) {
    sesjaWczytana = (async () => {
      if (!authConfigured()) return;
      try {
        const raw = await AsyncStorage.getItem(K_SESSION);
        // Sesji zapisanej w międzyczasie (logowanie z linku) nie nadpisujemy.
        if (!session) session = raw ? JSON.parse(raw) : null;
      } catch {
        /* brak odczytu = gość; `restore()` spróbuje jeszcze raz */
      }
    })();
  }
  return sesjaWczytana;
}

wczytajSesje();

export async function restore(): Promise<AuthUser | null> {
  if (!authConfigured()) return null;
  await wczytajSesje();
  if (!session) {
    await storeUser(null);
    return null;
  }
  const zapamietany = await cachedUser();
  const swiezy = await refreshUser();
  // `refreshUser` wyzerował profil tylko dlatego, że nie doszliśmy do serwera —
  // sesja nadal jest, więc trzymamy się tego, co wiemy z ostatniego razu
  if (!swiezy && session) {
    user = zapamietany;
    return zapamietany;
  }
  return swiezy;
}

/** Odświeżanie w locie — JEDNO na całą aplikację.
 *
 *  Bez tego konto wylatywało co chwilę i wyglądało to na kaprys serwera. Mechanizm
 *  był taki: każdy ekran woła po kilka endpointów naraz (`Promise.all`), a każde
 *  żądanie prosi tu o token. Gdy token akurat wygasł, WSZYSTKIE te żądania ruszały
 *  z tym samym `refresh_token`. Supabase obraca tokeny — pierwsze wywołanie dostaje
 *  nowy i unieważnia stary, więc reszta wraca z błędem „już użyty", a my na ten błąd
 *  kasowaliśmy sesję. Efekt: wystarczyło wejść na ekran po godzinie, żeby wylecieć.
 *
 *  Teraz pierwszy chętny odświeża, a pozostali czekają na ten sam wynik.
 */
let wLocie: Promise<string> | null = null;

async function odswiez(): Promise<string> {
  const rt = session?.refresh_token || "";
  if (!rt) {
    await store(null);
    await storeUser(null);
    return "";
  }
  try {
    await adopt(await gotrue("/token?grant_type=refresh_token", { refresh_token: rt }));
    return session?.access_token || "";
  } catch (e: any) {
    // Serwer odrzucił sesję (wylogowano wszędzie, konto skasowane) — dopiero to
    // jest powód do czyszczenia. Brak sieci albo śpiący serwer NIE JEST: token
    // zostaje na dysku i spróbujemy jeszcze raz przy następnym żądaniu.
    if (e instanceof AuthError && (e.status === 400 || e.status === 401 || e.status === 403)) {
      await store(null);
      await storeUser(null);
    }
    return "";
  }
}

/** Ważny token dostępowy albo pusty string. Odświeża sesję, gdy trzeba. */
export async function accessToken(): Promise<string> {
  // Pierwsze żądania ruszają, zanim `restore()` zdąży zajrzeć do pamięci — bez
  // tego czekania wychodziły bez tokenu i serwer oddawał portfel pokazowy.
  if (!session) await wczytajSesje();
  if (!session) return "";
  const now = Math.floor(Date.now() / 1000);
  // zapas 5 minut, nie 60 sekund: token ma nie wygasnąć w połowie serii żądań
  if (session.expires_at - 300 > now) return session.access_token || "";

  if (!wLocie) {
    wLocie = odswiez().finally(() => { wLocie = null; });
  }
  return wLocie;
}

async function refreshUser(): Promise<AuthUser | null> {
  const t = await accessToken();
  if (!t) return null;
  try {
    const js = await gotrue("/user", undefined, t);
    await storeUser(toUser(js));
  } catch (e: any) {
    // konto skasowane albo token unieważniony — dopiero wtedy zapominamy profil
    if (e instanceof AuthError && (e.status === 401 || e.status === 403)) {
      await storeUser(null);
    } else {
      user = null;   // chwilowy brak łączności; profil w pamięci zostaje
    }
  }
  return user;
}

export async function signIn(email: string, password: string) {
  return adopt(await gotrue("/token?grant_type=password",
                            { email: email.trim(), password }));
}

export async function signUp(email: string, password: string) {
  const js = await gotrue("/signup", { email: email.trim(), password });
  // przy włączonym potwierdzaniu adresu konto powstaje bez sesji
  return js?.access_token ? adopt(js) : null;
}

export async function signOut() {
  const t = session?.access_token;
  if (t) { try { await gotrue("/logout", {}, t); } catch { /* i tak czyścimy lokalnie */ } }
  await store(null);
  await storeUser(null);
  // następne logowanie Google ma zapytać, na które konto — bez tego przeglądarka
  // systemowa wraca po cichu z tym samym kontem, co przed wylogowaniem
  try { await AsyncStorage.setItem(K_PICK, "1"); } catch { /* nie warto przerywać wylogowania */ }
}

/* ------------------------------------------------------------ logowanie Google */

/** Adres, na który Supabase odsyła po zalogowaniu Google.
 *
 *  W Expo Go jest to `exp://…/--/auth-callback`, w zbudowanej aplikacji
 *  `portfel://auth-callback`. Oba trzeba mieć dopisane w Supabase w
 *  „Authentication → URL Configuration → Redirect URLs".
 *
 *  UWAGA po zmianie nazwy na Portevo: `app.json` rejestruje OBA schematy
 *  (`portevo` i `portfel`), a tu nadal zwracamy stary — bo w Supabase wpisany
 *  jest tylko `portfel://auth-callback`. Gdy dopiszesz tam `portevo://auth-callback`,
 *  zmień poniższą linię i wtedy dopiero można usunąć `portfel` z `scheme`.
 */
export function redirectUrl(): string {
  try {
    const Constants = require("expo-constants").default;
    const base: string = Constants?.linkingUri || "";
    if (base) return base.replace(/\/?$/, "") + (base.includes("--") ? "/auth-callback" : "/--/auth-callback");
  } catch { /* poza Expo Go schodzimy na własny schemat */ }
  return "portfel://auth-callback";
}

/** Wyciąga tokeny z adresu powrotnego — Supabase wkłada je we fragment (#) albo w query. */
function tokensFromUrl(url: string): Session | null {
  const at = /[#?&]access_token=([^&]+)/.exec(url);
  if (!at) return null;
  const rt = /[#?&]refresh_token=([^&]+)/.exec(url);
  const ei = /[#?&]expires_in=(\d+)/.exec(url);
  return {
    access_token: decodeURIComponent(at[1]),
    refresh_token: rt ? decodeURIComponent(rt[1]) : "",
    expires_at: Math.floor(Date.now() / 1000) + (ei ? parseInt(ei[1], 10) : 3600),
  };
}

/** Otwiera logowanie Google w przeglądarce systemowej i czeka na powrót do aplikacji.
 *
 *  Na iOS/Android używamy `WebBrowser.openAuthSessionAsync` — logowanie odbywa się
 *  w natywnym oknie auth (SFAuthenticationSession / Custom Tabs), które wraca
 *  do aplikacji płynnie, bez systemowego dialogu „Czy chcesz otworzyć link?".
 *  Na webowej wersji (Platform.OS === 'web') wracamy do starego `Linking.openURL`.
 */
export async function signInGoogle(): Promise<AuthUser | null> {
  if (!authConfigured()) throw new Error("Logowanie nie jest skonfigurowane");
  const redirect = redirectUrl();
  console.log("[auth] redirect_to =", redirect);

  /* Po wylogowaniu prosimy Google o ekran wyboru konta — inaczej nie da się
     przesiąść na inne. Znacznik zdejmujemy od razu: normalne logowanie na
     urządzeniu ma być bezobsługowe. */
  let extra = "";
  try {
    if (await AsyncStorage.getItem(K_PICK)) {
      extra = "&prompt=select_account";
      await AsyncStorage.removeItem(K_PICK);
    }
  } catch { /* brak znacznika to nie powód, żeby nie logować */ }

  const url = `${SUPABASE_URL}/auth/v1/authorize?provider=google`
            + `&redirect_to=${encodeURIComponent(redirect)}${extra}`;

  /* --- web: stary sposób (Linking + listener) --- */
  if (Platform.OS === "web") {
    return new Promise((resolve, reject) => {
      let done = false;
      const finish = async (cbUrl: string) => {
        if (done) return;
        const s = tokensFromUrl(cbUrl);
        if (!s) return;
        done = true;
        sub.remove();
        clearTimeout(timer);
        await store(s);
        resolve(await refreshUser());
      };
      const sub = Linking.addEventListener("url", (e) => { finish(e.url); });
      const timer = setTimeout(() => {
        if (done) return;
        done = true;
        sub.remove();
        resolve(null);
      }, 5 * 60 * 1000);
      Linking.openURL(url).catch((e) => {
        done = true;
        sub.remove();
        clearTimeout(timer);
        reject(e);
      });
    });
  }

  /* --- iOS / Android: in-app auth session (bez brzydkiego dialogu) --- */
  const result = await WebBrowser.openAuthSessionAsync(url, redirect);

  if (result.type === "success" && result.url) {
    const s = tokensFromUrl(result.url);
    if (!s) return null;
    await store(s);
    return refreshUser();
  }

  // użytkownik zamknął okno lub anulował
  return null;
}

/** Obsługa linku, którym aplikacja została uruchomiona (zimny start po logowaniu). */
export async function consumeInitialUrl(): Promise<AuthUser | null> {
  try {
    const url = await Linking.getInitialURL();
    if (!url) return null;
    const s = tokensFromUrl(url);
    if (!s) return null;
    await store(s);
    return refreshUser();
  } catch {
    return null;
  }
}
