/** Prześwietlenie funduszu doklejone pod wykresem instrumentu.
 *
 *  Pojawia się wszędzie tam, gdzie użytkownik ogląda ETF — z portfela, z listy
 *  obserwowanych, z wyszukiwarki. Sens jest prosty: patrzysz na wykres funduszu,
 *  który masz w portfelu, i tu na dole dowiadujesz się, co w nim właściwie siedzi.
 *
 *  Skrócona wersja tego, co pokazuje pełna karta w Skanerze ETF — z przyciskiem
 *  otwierającym tamtą kartę w całości.
 */
import React, { useEffect, useState } from "react";
import { ActivityIndicator, StyleSheet, Text, View } from "react-native";
import { EtfDetail, getEtfDetail } from "../../api";
import { useAuth } from "../../auth/AuthContext";
import PremiumGate from "../../components/PremiumGate";
import { C, chartColor, T } from "../../theme";
import { Bar, Card, FadeIn, MetalButton, SectionTitle } from "../../ui";
import EtfDetailModal from "./EtfDetailModal";

const GOLD = "#ffc45c";

/** Czy dla tego instrumentu w ogóle warto pokazywać sekcję funduszu. */
export function looksLikeEtf(symbol: string, name = "", type = ""): boolean {
  if ((type || "").toUpperCase() === "ETF") return true;
  const n = (name || "").toLowerCase();
  return /etf|ucits|index fund/.test(n);
}

export default function EtfXrayCard({
  symbol, name, type,
}: { symbol: string; name?: string; type?: string }) {
  const { locked } = useAuth();
  const isLocked = locked("tools.etf");
  const [d, setD] = useState<EtfDetail | null>(null);
  const [tried, setTried] = useState(false);
  const [full, setFull] = useState(false);

  useEffect(() => {
    if (!looksLikeEtf(symbol, name, type)) return;
    // bez premium nie ruszamy serwera — pod kłódką i tak stoi szkielet
    if (isLocked) { setTried(true); return; }
    let alive = true;
    getEtfDetail(symbol)
      .then((r) => { if (alive) setD(r); })
      .catch(() => {})
      .finally(() => { if (alive) setTried(true); });
    return () => { alive = false; };
  }, [symbol, isLocked]);

  if (!looksLikeEtf(symbol, name, type)) return null;
  // fundusz, którego Yahoo nie zna — lepiej nic nie pokazywać niż pustą sekcję
  if (!isLocked && tried && (!d || d.error || (!d.holdings.length && !d.sectors.length))) return null;

  return (
    <FadeIn delay={120}>
      <SectionTitle hint="To jest fundusz — zobacz, co naprawdę kupujesz razem z nim">
        Wnętrze funduszu
      </SectionTitle>

      <PremiumGate id="tools.etf" minHeight={330} bullets={3}
                   title="Prześwietlenie funduszu"
                   tagline="Skład, branże, koszt i realne ryzyko — po ludzku">
        {d ? <Body d={d} onFull={() => setFull(true)} /> : <Skeleton />}
      </PremiumGate>

      {full && d && (
        <EtfDetailModal symbol={d.symbol} onClose={() => setFull(false)} />
      )}
    </FadeIn>
  );
}

function Body({ d, onFull }: { d: EtfDetail; onFull: () => void }) {
  const risk = riskColor(d.risk.score);
  return (
    <Card style={s.card}>
      <View style={s.head}>
        <View style={{ flex: 1 }}>
          <Text style={s.title} numberOfLines={2}>{d.long_name || d.name}</Text>
          <Text style={s.meta}>
            {[d.catalog.region_label, d.catalog.sector_label,
              d.catalog.acc == null ? "" : d.catalog.acc ? "akumulujący" : "wypłacający"]
              .filter(Boolean).join(" · ")}
          </Text>
        </View>
        <View style={[s.riskPill, { borderColor: risk + "88", backgroundColor: risk + "1a" }]}>
          <Text style={[s.riskPillTxt, { color: risk }]}>
            {d.risk.score ? `${d.risk.score}/5` : "—"}
          </Text>
        </View>
      </View>

      <View style={s.stats}>
        <Stat label="Koszt roczny"
              value={d.profile.ter_pct != null ? `${d.profile.ter_pct.toFixed(2)}%` : "—"}
              hint={d.profile.ter_pct != null
                ? `${Math.round(10000 * d.profile.ter_pct / 100)} zł rocznie z 10 tys.`
                : "brak danych"} />
        <Stat label="Wahania"
              value={d.risk.vol_pct != null ? `${d.risk.vol_pct.toFixed(0)}%` : "—"}
              hint="w skali roku" />
        <Stat label="Największy spadek"
              value={d.risk.max_dd_pct != null ? `−${d.risk.max_dd_pct.toFixed(0)}%` : "—"}
              hint="szczyt → dołek" />
      </View>

      {d.countries.length > 0 && (
        <View style={s.ctryRow}>
          {d.countries.slice(0, 3).map((cn) => (
            <View key={cn.code} style={s.ctryChip}>
              <Text style={s.ctryFlag}>{cn.flag}</Text>
              <Text style={s.ctryTxt}>
                {cn.pct.toFixed(0)}%<Text style={s.ctryName}> {cn.name}</Text>
              </Text>
            </View>
          ))}
        </View>
      )}

      {d.holdings.length > 0 && (
        <>
          <Text style={s.subTitle}>
            Największe pozycje
            {d.top10_pct != null && (
              <Text style={s.subTitleDim}>   dziesiątka to {d.top10_pct.toFixed(0)}% funduszu</Text>
            )}
          </Text>
          {d.holdings.slice(0, 5).map((h, i) => (
            <View key={h.symbol + i} style={s.row}>
              <Text style={s.rowName} numberOfLines={1}>{h.name}</Text>
              <Text style={s.rowPct}>{h.pct.toFixed(2)}%</Text>
              <Text style={s.rowMoney}>{h.per_1000.toFixed(0)} zł / 1000</Text>
            </View>
          ))}
          {/* fundusze z GPW: skład liczymy sami, więc mówimy o tym wprost */}
          {!!d.holdings_note && <Text style={s.srcNote}>{d.holdings_note}</Text>}
        </>
      )}

      {d.sectors.length > 0 && (
        <>
          <Text style={[s.subTitle, { marginTop: 16 }]}>Branże</Text>
          {d.sectors.slice(0, 4).map((sec, i) => (
            <View key={sec.id} style={{ marginTop: 10 }}>
              <View style={s.secRow}>
                <Text style={s.secName}>{sec.label}</Text>
                <Text style={s.secPct}>{sec.pct.toFixed(1)}%</Text>
              </View>
              <View style={{ marginTop: 5 }}>
                <Bar pct={sec.pct} color={chartColor(i)} delay={i * 40} />
              </View>
            </View>
          ))}
        </>
      )}

      <MetalButton label="Pełne prześwietlenie" tone="amber" active liquid full
                   style={{ marginTop: 18 }} onPress={onFull} />
    </Card>
  );
}

/** Szkielet pod kłódką: właściwy kształt, żadnych prawdziwych liczb. */
function Skeleton() {
  const bar = (w: any, h = 9) => (
    <View style={{ width: w, height: h, borderRadius: 5, backgroundColor: "rgba(255,255,255,.09)" }} />
  );
  return (
    <Card style={s.card}>
      <View style={s.head}>
        <View style={{ flex: 1, gap: 8 }}>{bar("78%", 15)}{bar("52%", 10)}</View>
        <View style={[s.riskPill, { borderColor: "rgba(255,255,255,.12)" }]}>
          <Text style={[s.riskPillTxt, { color: C.dim }]}>?/5</Text>
        </View>
      </View>
      <View style={s.stats}>
        {["Koszt roczny", "Wahania", "Największy spadek"].map((l) => (
          <View key={l} style={{ flex: 1, gap: 7 }}>
            <Text style={s.statLabel}>{l}</Text>
            {bar("58%", 17)}
          </View>
        ))}
      </View>
      <Text style={s.subTitle}>Największe pozycje</Text>
      <View style={{ gap: 13, marginTop: 6 }}>
        {[92, 71, 58, 44, 33].map((w, i) => (
          <View key={i} style={{ gap: 6 }}>
            {bar(`${Math.min(70, w)}%`, 8)}
            <Bar pct={w} color={chartColor(i)} />
          </View>
        ))}
      </View>
    </Card>
  );
}

function Stat({ label, value, hint }: { label: string; value: string; hint: string }) {
  return (
    <View style={{ flex: 1 }}>
      <Text style={s.statLabel}>{label}</Text>
      <Text style={s.statVal}>{value}</Text>
      <Text style={s.statHint}>{hint}</Text>
    </View>
  );
}

function riskColor(score: number | null) {
  if (score == null) return C.dim;
  return [C.green, C.green, C.amber, "#ff8a3d", C.red][Math.min(4, Math.max(0, score - 1))];
}

const s = StyleSheet.create({
  card: { padding: 16 },
  head: { flexDirection: "row", alignItems: "flex-start", gap: 12 },
  title: { color: C.text, fontSize: 14.5, fontWeight: "800", lineHeight: 20 },
  meta: { color: C.dim, fontSize: 11.5, marginTop: 4 },
  riskPill: { borderRadius: 999, borderWidth: 1, paddingHorizontal: 10, paddingVertical: 4 },
  riskPillTxt: { fontSize: 11, fontWeight: "800" },

  stats: { flexDirection: "row", gap: 12, marginTop: 18 },
  statLabel: { color: C.dim, fontSize: 10, fontWeight: "700", letterSpacing: 0.4 },
  statVal: { color: C.text, fontSize: 17, fontWeight: "800", marginTop: 4 },
  statHint: { color: C.dim, fontSize: 10, marginTop: 2, lineHeight: 13 },

  subTitle: { color: C.text, fontSize: 13, fontWeight: "800", marginTop: 20, marginBottom: 4 },
  subTitleDim: { color: C.dim, fontSize: 11, fontWeight: "600" },
  srcNote: { color: C.dim, fontSize: 10.5, lineHeight: 15, marginTop: 9 },

  row: {
    flexDirection: "row", alignItems: "center", gap: 10, paddingVertical: 8,
    borderBottomWidth: 1, borderBottomColor: "rgba(33,41,56,.55)",
  },
  rowName: { color: C.muted, fontSize: 12.5, flex: 1 },
  rowPct: { color: C.text, fontSize: 12.5, fontWeight: "800", width: 52, textAlign: "right" },
  rowMoney: { color: GOLD, fontSize: 10.5, fontWeight: "700", width: 86, textAlign: "right" },

  ctryRow: { flexDirection: "row", flexWrap: "wrap", gap: 6, marginTop: 16 },
  ctryChip: {
    flexDirection: "row", alignItems: "center", gap: 5, borderRadius: 999,
    paddingVertical: 4, paddingHorizontal: 9,
    backgroundColor: "rgba(255,255,255,.05)", borderWidth: 1, borderColor: C.border,
  },
  ctryFlag: { fontSize: 13 },
  ctryTxt: { color: C.text, fontSize: 11, fontWeight: "800" },
  ctryName: { color: C.dim, fontSize: 10.5, fontWeight: "600" },

  secRow: { flexDirection: "row", justifyContent: "space-between" },
  secName: { color: C.muted, fontSize: 12.5 },
  secPct: { color: C.text, fontSize: 12.5, fontWeight: "700" },
});
