/* ══════════════════════════════════════════════════════════ drobne animacje */

/** Zegar 1 Hz — odliczanie ma płynąć niezależnie od odświeżania danych z serwera. */
function useTick(): number {
  const [now, setNow] = useState(() => Date.now() / 1000);
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now() / 1000), 1000);
    return () => clearInterval(t);
  }, []);
  return now;
}

/** Liczba dobiegająca do wartości — bo „46 848" wjeżdżające na ekran czyta się
 *  jako skala działania, a to samo „46 848" postawione od razu czyta się jak etykieta. */
function useCountUp(target: number, duration = 1100): number {
  const [v, setV] = useState(0);
  useEffect(() => {
    if (!target) { setV(0); return; }
    const start = Date.now();
    const id = setInterval(() => {
      const p = Math.min(1, (Date.now() - start) / duration);
      setV(Math.round(target * (1 - Math.pow(1 - p, 3))));   // wyhamowanie na końcu
      if (p >= 1) clearInterval(id);
    }, 40);
    return () => clearInterval(id);
  }, [target, duration]);
  return v;
}

/** Kropka „to dzieje się teraz" z rozchodzącym się pierścieniem. */
function LiveDot({ color = C.green, size = 9, on = true }: {
  color?: string; size?: number; on?: boolean;
}) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    if (!on) return;
    const loop = Animated.loop(Animated.timing(a, {
      toValue: 1, duration: 1900, easing: Easing.out(Easing.quad), useNativeDriver: true,
    }));
    loop.start();
    return () => loop.stop();
  }, [on]);

  return (
    <View style={{ width: size, height: size }}>
      {on && (
        <Animated.View
          pointerEvents="none"
          style={{
            position: "absolute", left: 0, top: 0, width: size, height: size,
            borderRadius: size, borderWidth: 1.5, borderColor: color,
            opacity: a.interpolate({ inputRange: [0, 1], outputRange: [0.55, 0] }),
            transform: [{ scale: a.interpolate({ inputRange: [0, 1], outputRange: [1, 3] }) }],
          }}
        />
      )}
      <View style={{
        width: size, height: size, borderRadius: size,
        backgroundColor: on ? color : C.dim,
      }} />
    </View>
  );
}

/** Przelatujący błysk — używany na obwódce nagłówka i na złotym przycisku. */
function Sheen({ width, delay = 2400, tint = "rgba(255,255,255,.35)" }: {
  width: number; delay?: number; tint?: string;
}) {
  const a = useRef(new Animated.Value(0)).current;
  useEffect(() => {
    const loop = Animated.loop(Animated.sequence([
      Animated.delay(delay),
      Animated.timing(a, {
        toValue: 1, duration: 1500, easing: Easing.inOut(Easing.quad), useNativeDriver: true,
      }),
      Animated.timing(a, { toValue: 0, duration: 0, useNativeDriver: true }),
    ]));
    loop.start();
    return () => loop.stop();
  }, [width, delay]);

  if (!width) return null;
  return (
    <Animated.View
      pointerEvents="none"
      style={{
        position: "absolute", top: -60, bottom: -60, width: 90,
        opacity: a.interpolate({ inputRange: [0, 0.2, 0.8, 1], outputRange: [0, 0.6, 0.6, 0] }),
        transform: [
          { translateX: a.interpolate({ inputRange: [0, 1], outputRange: [-120, width + 120] }) },
          { rotate: "14deg" },
        ],
      }}
    >
      <LinearGradient
        colors={["rgba(255,255,255,0)", tint, "rgba(255,255,255,0)"]}
        start={{ x: 0, y: 0 }} end={{ x: 1, y: 0 }}
        style={StyleSheet.absoluteFill as any}
      />
    </Animated.View>
  );
}

