/** Techniczna nazwa źródła („gpw_espi") na ludzką („GPW — komunikaty ESPI"). */
function etykietaZrodla(klucz: string): string {
  const mapa: Record<string, string> = {
    gpw_espi: "GPW — komunikaty ESPI", sec_edgar: "SEC EDGAR", squawk: "Terminal / X",
    truth_social: "Truth Social", rss: "Departamenty USA", knf: "KNF",
    live_event: "wystąpienie na żywo",
  };
  return mapa[klucz] || klucz;
}

function Metric({ value, label, tint }: { value: string; label: string; tint: string }) {
  return (
    <View style={h.metric}>
      <Text style={[h.metricVal, { color: tint }]} numberOfLines={1} adjustsFontSizeToFit>
        {value}
      </Text>
      <Text style={h.metricLbl}>{label}</Text>
    </View>
  );
}

/* ═════════════════════════════════════════════════════════ nasłuch na żywo */

function LiveSources({ sc, serverNow }: { sc: Showcase | null; serverNow: number }) {
  const stan = new Map((sc?.sources || []).map((z) => [z.key, z]));
  const zyje = Boolean(sc?.bot_alive) && !sc?.paused;

  return (
    <View>
      {SOURCES.map((src, i) => {
        const z = stan.get(src.poll);
        const on = z ? z.enabled : false;
        const interval = z?.interval || 0;
        const since = z?.ts ? serverNow - z.ts : null;
        const left = interval && since != null ? Math.max(0, interval - since) : null;
        const pct = interval && since != null
          ? Math.max(2, Math.min(100, (since / interval) * 100)) : 0;

        let status = "wyłączone";
        let statusColor = C.dim;
        if (on && !zyje) { status = "czeka na start"; statusColor = C.muted; }
        else if (on && zyje && !z?.ts) { status = "pierwsze sprawdzenie…"; statusColor = C.amber; }
        else if (on && zyje && left != null) {
          status = left < 1 ? "sprawdzam…" : `za ${Math.ceil(left)} s`;
          statusColor = left < 1 ? C.amber : C.green;
        }

        return (
          <FadeIn key={src.poll} delay={Math.min(i * 55, 320)} offset={10}>
            <Card style={[l.card, !on && l.cardOff]}>
              <View style={l.row}>
                <View style={[l.badge, {
                  backgroundColor: src.color + "22", borderColor: src.color + "55",
                }]}>
                  <Text style={[l.badgeTxt, { color: src.color }]}>{src.badge}</Text>
                </View>
                <View style={{ flex: 1, marginLeft: 10 }}>
                  <Text style={l.name}>{src.name}</Text>
                  <Text style={l.desc}>{src.desc}</Text>
                </View>
                {on && <LiveDot on={zyje} size={8} color={src.color} />}
              </View>

              {on && (
                <>
                  <View style={l.track}>
                    <View style={[l.fill, {
                      width: `${pct}%`, backgroundColor: zyje ? src.color : C.dim,
                    }]} />
                  </View>
                  <View style={l.metaRow}>
                    <Text style={[l.status, { color: statusColor }]}>{status}</Text>
                    <Text style={l.meta}>
                      {interval ? every(interval) : "—"}
                      {since != null ? `  ·  ostatnio ${ago(since)}` : ""}
                    </Text>
                  </View>
                </>
              )}
            </Card>
          </FadeIn>
        );
      })}
    </View>
  );
}

