function Pipeline({ sc }: { sc: Showcase | null }) {
  const etapy = buildEtapy(sc);
  const [open, setOpen] = useState<string>(etapy[0].id);
  const detal = etapy.find((e) => e.id === open) || etapy[0];

  return (
    <View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false}
                  contentContainerStyle={p.rail}>
        {etapy.map((e, i) => {
          const aktywny = open === e.id;
          return (
            <React.Fragment key={e.id}>
              {i > 0 && <Text style={p.arrow}>›</Text>}
              <Press onPress={() => setOpen(e.id)} scaleTo={0.95}
                     style={[p.node, aktywny && p.nodeOn]}>
                <Text style={p.nodeNum}>{i + 1}</Text>
                <View style={p.nodeIco}><Icon name={e.ico} size={19} color={aktywny ? C.green : C.muted} /></View>
                <Text style={[p.nodeTitle, aktywny && { color: C.green }]}>{e.title}</Text>
                <Text style={p.nodeSub} numberOfLines={2}>{e.sub}</Text>
              </Press>
            </React.Fragment>
          );
        })}
      </ScrollView>

      <FadeIn key={detal.id} offset={10}>
        <Card style={p.detail}>
          <View style={p.detailHeadRow}>
            <Icon name={detal.ico} size={17} color={C.green} />
            <Text style={p.detailHead}>{detal.head}</Text>
          </View>
          <Text style={p.detailIntro}>{detal.intro}</Text>
          {detal.rows.filter(([, v]) => v !== "").map(([k, v]) => (
            <View key={k} style={p.row}>
              <Text style={p.rowK}>{k}</Text>
              <Text style={p.rowV}>{v}</Text>
            </View>
          ))}
          {!!detal.note && <Text style={p.note}>{detal.note}</Text>}
        </Card>
      </FadeIn>
    </View>
  );
}

