function GoldCTA({ onPress, cena }: { onPress: () => void; cena: string | null }) {
  const [w, setW] = useState(0);
  const scale = useRef(new Animated.Value(1)).current;
  const spring = (to: number) =>
    Animated.spring(scale, { toValue: to, useNativeDriver: true, speed: 45, bounciness: 5 }).start();

  return (
    <Pressable onPressIn={() => spring(0.98)} onPressOut={() => spring(1)} onPress={onPress}>
      <Animated.View onLayout={(e) => setW(e.nativeEvent.layout.width)}
                     style={{ transform: [{ scale }] }}>
        <LinearGradient
          colors={[GOLD, "rgba(255,196,92,.45)", GOLD_DEEP]}
          start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
          style={g.edge}
        >
          <View style={g.face}>
            <LinearGradient
              pointerEvents="none"
              colors={["rgba(255,196,92,.16)", "rgba(20,16,8,0)"]}
              start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
              style={StyleSheet.absoluteFill as any}
            />
            <Sheen width={w} tint="rgba(255,214,140,.45)" delay={2000} />

            <Text style={g.title}>Odblokuj bota newsowego</Text>
            <Text style={g.sub}>
              Pełne analizy z uzasadnieniem, edytowalny Mózg AI, statystyka sprawdzalności
              i wystąpienia na żywo — w jednym pakiecie z resztą funkcji premium.
            </Text>

            <View style={g.btn}>
              <Text style={g.btnTxt}>Zobacz, co daje premium</Text>
              <Text style={g.btnArrow}>→</Text>
            </View>
            {!!cena && <Text style={g.price}>{cena}</Text>}
          </View>
        </LinearGradient>
      </Animated.View>
    </Pressable>
  );
}

/* ════════════════════════════════════════════════════════════════════ ekran */

export default function BotShowcase() {
  const { showPaywall, catalog } = useAuth();
  const [sc, setSc] = useState<Showcase | null>(null);
  const now = useTick();

  const load = useCallback(async () => {
    try { setSc(await getBotShowcase()); } catch { /* strona ma działać i bez serwera */ }
  }, []);

  useEffect(() => { load(); }, [load]);

  // odświeżamy rzadko (dane zmieniają się co kilkanaście sekund), a odliczanie i tak
  // płynie z lokalnego zegara; w tle nic nie pobieramy
  useEffect(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => { if (!timer) timer = setInterval(load, 25000); };
    const stop = () => { if (timer) { clearInterval(timer); timer = null; } };
    const sub = AppState.addEventListener("change", (s) => {
      if (s === "active") { load(); start(); } else stop();
    });
    start();
    return () => { stop(); sub.remove(); };
  }, [load]);

  useEffect(() => { trackPremium("showcase_seen", "bot.signals"); }, []);

  // zegar telefonu bywa przesunięty względem serwera — odliczamy w czasie serwera
  const offset = sc?.server_time ? Date.now() / 1000 - sc.server_time : 0;
  const serverNow = now - offset;

  const plan = (catalog?.plans || []).find((x) => x.id === "monthly");
  const cena = plan ? `Od ${plan.price} ${plan.currency} / ${plan.period} · ${plan.note}` : null;

  return (
    <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
      {/* właściciel w trybie podglądu — jednym dotknięciem wraca do pełnej wersji */}
      <PreviewBanner />

      <FadeIn><Hero sc={sc} /></FadeIn>

      <Naglowek title="Nasłuch na żywo"
                hint="To nie jest animacja poglądowa. Paski pokazują, ile czasu minęło od
                      ostatniego sprawdzenia każdego kanału na serwerze." />
      <LiveSources sc={sc} serverNow={serverNow} />

      <Naglowek title="Jak bot dochodzi do wniosku"
                hint="Każda wiadomość idzie tą ścieżką od lewej do prawej. Dotknij etapu,
                      żeby zobaczyć, co się w nim dzieje i jakie wartości teraz obowiązują." />
      <Pipeline sc={sc} />

      <Naglowek title="Co z tego masz" />
      {KORZYSCI.map((k, i) => (
        <FadeIn key={k.title} delay={Math.min(i * 70, 300)} offset={10}>
          <Card style={b.card}>
            <View style={[b.ico, { backgroundColor: k.tint + "1c", borderColor: k.tint + "44" }]}>
              <Icon name={k.ico} size={17} color={k.tint} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={b.title}>{k.title}</Text>
              <Text style={b.txt}>{k.txt}</Text>
            </View>
          </Card>
        </FadeIn>
      ))}

      <View style={{ marginTop: 22 }}>
        <GoldCTA cena={cena} onPress={() => showPaywall("bot.signals")} />
      </View>

      <Text style={s.foot}>
        Bot nie składa zleceń i nie łączy się z żadnym brokerem. Materiał informacyjny —
        to nie jest porada inwestycyjna ani rekomendacja.
      </Text>
    </ScrollView>
  );
}

function Naglowek({ title, hint }: { title: string; hint?: string }) {
  return (
    <View style={s.head}>
      <Text style={s.headTitle}>{title}</Text>
      {!!hint && <Text style={s.headHint}>{hint.replace(/\s+/g, " ").trim()}</Text>}
    </View>
  );
}

