/** Szczegóły wydarzenia ekonomicznego.
 *
 *  Trzy warstwy informacji: co i kiedy (nagłówek), jakie są liczby (odczyt vs
 *  prognoza vs poprzednio), i po co komu ten wskaźnik (opis źródła + wykres
 *  poprzednich publikacji).
 *
 *  Opis przychodzi po angielsku — to język tego kalendarza i tłumaczenie maszynowe
 *  zrobiłoby z niego kaszę. Nazwę wskaźnika i wszystko dookoła mamy po polsku.
 */
import React, { useEffect, useState } from "react";
import {
  ActivityIndicator, Modal, Platform, SafeAreaView, ScrollView, StatusBar,
  StyleSheet, Text, View,
} from "react-native";
import { EconEvent, EventDetail, getEventDetail } from "../../api";
import { C, T } from "../../theme";
import { Card, ErrorBoundary, FadeIn, MetalButton, Press, SectionTitle } from "../../ui";
import { IndicatorChart } from "./charts";
import { bankTag, hhmm, toneOf } from "./EventChip";

import Icon from "../../ui/Icon";
const KIND_LABEL: Record<string, string> = {
  fed: "Rezerwa Federalna", cb: "Bank centralny", speech: "Wystąpienie",
  holiday: "Dzień wolny", data: "Odczyt danych",
};

const IMPORTANCE_LABEL = ["kosmetyczna", "niska", "średnia", "wysoka"];

const PERIOD_PL: Record<string, string> = {
  MONTH: "miesięczny", QUARTER: "kwartalny", YEAR: "roczny", WEEK: "tygodniowy",
  DAY: "dzienny",
};

export default function EventModal({
  event, onClose,
}: { event: EconEvent | null; onClose: () => void }) {
  const [detail, setDetail] = useState<EventDetail | null>(null);
  const [loading, setLoading] = useState(true);

  //  Jak w raporcie spółki: opis poprzedniego wydarzenia nie może dojechać
  //  do już otwartego następnego.
  useEffect(() => {
    if (!event) return;
    let current = true;
    setLoading(true);
    setDetail(null);
    getEventDetail(event.event_id, event.country)
      .then((d) => { if (current) setDetail(d); })
      .catch(() => {})
      .finally(() => { if (current) setLoading(false); });
    return () => { current = false; };
  }, [event?.event_id]);

  if (!event) return <Modal visible={false}><View /></Modal>;

  const tone = toneOf(event);
  const bank = event.kind === "fed" || event.kind === "cb";
  const history = detail?.history || [];

  return (
    <Modal visible animationType="slide" onRequestClose={onClose}
           presentationStyle="fullScreen" statusBarTranslucent>
      <ErrorBoundary name="Wydarzenie" resetKey={event.event_id}
                     onDismiss={onClose} dismissLabel="Zamknij">
      <SafeAreaView style={s.root}>
        <StatusBar barStyle="light-content" />
        <View style={s.bar}>
          <Press onPress={onClose} style={s.close}><Icon name="zamknij" size={15} color={C.muted} /></Press>
          <Text style={s.barTitle} numberOfLines={1}>Wydarzenie ekonomiczne</Text>
        </View>

        <ScrollView contentContainerStyle={s.wrap} showsVerticalScrollIndicator={false}>
          <FadeIn>
            <View style={s.head}>
              <View style={[s.flagBox, { borderColor: tone + "55" }]}>
                <Text style={s.flag}>{event.flag}</Text>
              </View>
              <View style={{ flex: 1 }}>
                <Text style={s.name}>{event.name_pl}</Text>
                {event.name_pl !== event.name && (
                  <Text style={s.orig}>{event.name}</Text>
                )}
              </View>
            </View>

            <View style={s.badges}>
              {bank && <Badge tone={tone} label={bankTag(event)} solid />}
              <Badge tone={tone} label={KIND_LABEL[event.kind] || event.kind} />
              <Badge tone={C.dim} label={event.country_name} />
              <Badge tone={event.importance >= 3 ? C.amber : C.dim}
                     label={`waga ${IMPORTANCE_LABEL[event.importance]}`} />
              {event.preliminary && <Badge tone={C.dim} label="odczyt wstępny" />}
              {event.tentative && <Badge tone={C.dim} label="termin orientacyjny" />}
            </View>

            <Card style={{ marginTop: 16 }}>
              <View style={s.whenRow}>
                <View>
                  <Text style={s.micro}>TERMIN</Text>
                  <Text style={s.when}>{event.date}</Text>
                </View>
                <View style={{ alignItems: "flex-end" }}>
                  <Text style={s.micro}>GODZINA</Text>
                  <Text style={[s.when, { color: tone }]}>{hhmm(event)}</Text>
                </View>
              </View>
              {!!event.period_date && (
                <Text style={s.periodTxt}>
                  Okres {PERIOD_PL[event.period] || event.period.toLowerCase()}: {event.period_date}
                </Text>
              )}
            </Card>
          </FadeIn>

          {/* ---------- liczby ---------- */}
          {(!!event.actual_fmt || !!event.consensus_fmt || !!event.previous_fmt) && (
            <>
              <SectionTitle hint="Rynek reaguje nie na sam poziom, tylko na różnicę między odczytem a prognozą.">
                Liczby
              </SectionTitle>
              <View style={s.nums}>
                <Num label="Odczyt" value={event.actual_fmt || "—"}
                     tone={event.actual == null ? C.dim
                       : event.better === false ? C.red : event.better ? C.green : C.text}
                     big />
                <Num label="Prognoza" value={event.consensus_fmt || "—"} tone={C.muted} />
                <Num label="Poprzednio" value={event.previous_fmt || "—"} tone={C.dim} />
              </View>
              {event.actual != null && event.consensus != null && (
                <Text style={s.verdict}>
                  {event.actual > event.consensus
                    ? `Odczyt wyższy od prognozy o ${fmtDiff(event.actual - event.consensus)}.`
                    : event.actual < event.consensus
                      ? `Odczyt niższy od prognozy o ${fmtDiff(event.consensus - event.actual)}.`
                      : "Odczyt dokładnie zgodny z prognozą."}
                  {detail?.rise === "POSITIVE"
                    ? ` Wyższa wartość jest zwykle korzystna dla ${event.currency}.`
                    : detail?.rise === "NEGATIVE"
                      ? ` Wyższa wartość jest zwykle niekorzystna dla ${event.currency}.` : ""}
                </Text>
              )}
            </>
          )}

          {/* ---------- historia ---------- */}
          {loading ? (
            <View style={s.loading}><ActivityIndicator color={C.green} /></View>
          ) : (
            <>
              {history.length >= 2 && (
                <>
                  <SectionTitle hint="Ostatnie publikacje tego samego wskaźnika. Linia ciągła to rzeczywisty odczyt, przerywana — prognoza rynku.">
                    Poprzednie odczyty
                  </SectionTitle>
                  <Card><IndicatorChart data={history} /></Card>
                </>
              )}

              {!!detail?.description && (
                <>
                  <SectionTitle hint={detail.category ? `Kategoria: ${detail.category}` : undefined}>
                    Co to właściwie jest
                  </SectionTitle>
                  <Card>
                    <Text style={s.desc}>{detail.description}</Text>
                    {!!detail.source_name && (
                      <Text style={s.source}>Źródło danych: {detail.source_name}</Text>
                    )}
                  </Card>
                </>
              )}
            </>
          )}

          <View style={{ marginTop: 26 }}>
            <MetalButton label="Zamknij" full size="lg" onPress={onClose} />
          </View>
        </ScrollView>
      </SafeAreaView>
      </ErrorBoundary>
    </Modal>
  );
}

const fmtDiff = (v: number) =>
  Math.abs(v).toLocaleString("pl-PL", { maximumFractionDigits: 2 });

function Num({ label, value, tone, big }: {
  label: string; value: string; tone: string; big?: boolean;
}) {
  return (
    <View style={[s.num, big && { borderColor: tone + "44" }]}>
      <Text style={s.numLabel}>{label}</Text>
      <Text style={[s.numValue, { color: tone }, big && { fontSize: 20 }]} numberOfLines={1}>
        {value}
      </Text>
    </View>
  );
}

function Badge({ tone, label, solid }: { tone: string; label: string; solid?: boolean }) {
  return (
    <View style={[s.badge, {
      borderColor: tone + "66",
      backgroundColor: solid ? tone : tone + "14",
    }]}>
      <Text style={[s.badgeTxt, { color: solid ? "#0a0d13" : tone }]}>{label}</Text>
    </View>
  );
}

const s = StyleSheet.create({
  root: { flex: 1, backgroundColor: C.bg, paddingTop: Platform.OS === "android" ? 26 : 0 },
  bar: {
    flexDirection: "row", alignItems: "center", gap: 12,
    paddingHorizontal: 14, paddingVertical: 10,
    borderBottomWidth: 1, borderBottomColor: C.border,
  },
  close: {
    width: 34, height: 34, borderRadius: 17, alignItems: "center", justifyContent: "center",
    backgroundColor: C.card, borderWidth: 1, borderColor: C.border,
  },
  closeTxt: { color: C.muted, fontSize: 15, fontWeight: "800" },
  barTitle: { color: C.text, ...T.h2, flex: 1 },
  wrap: { padding: 18, paddingBottom: 60 },

  head: { flexDirection: "row", alignItems: "center", gap: 13 },
  flagBox: {
    width: 52, height: 52, borderRadius: 15, alignItems: "center", justifyContent: "center",
    borderWidth: 1.5, backgroundColor: C.card,
  },
  flag: { fontSize: 26 },
  name: { color: C.text, ...T.h1 },
  orig: { color: C.dim, ...T.small, marginTop: 3 },
  badges: { flexDirection: "row", flexWrap: "wrap", gap: 7, marginTop: 13 },
  badge: { borderRadius: 8, borderWidth: 1, paddingHorizontal: 8, paddingVertical: 3.5 },
  badgeTxt: { fontSize: 9.5, fontWeight: "800", letterSpacing: 0.5 },

  whenRow: { flexDirection: "row", justifyContent: "space-between", alignItems: "flex-start" },
  micro: { color: C.dim, ...T.micro },
  when: { color: C.text, ...T.h2, marginTop: 4 },
  periodTxt: { color: C.dim, ...T.small, marginTop: 12 },

  nums: { flexDirection: "row", gap: 9 },
  num: {
    flex: 1, backgroundColor: C.card, borderRadius: 15, borderWidth: 1, borderColor: C.border,
    padding: 12,
  },
  numLabel: { color: C.dim, fontSize: 9.5, fontWeight: "800", letterSpacing: 0.4 },
  numValue: { fontSize: 15, fontWeight: "900", marginTop: 6, letterSpacing: -0.4 },
  verdict: { color: C.muted, ...T.small, marginTop: 12, lineHeight: 19 },

  loading: { paddingVertical: 40, alignItems: "center" },
  desc: { color: C.muted, fontSize: 13.5, lineHeight: 21 },
  source: { color: C.dim, ...T.small, marginTop: 12 },
});
