/** Kanały YouTube — skąd bot sam wyłapuje wejścia na antenę.
 *
 *  Dozór odpytuje te kanały cyklicznie i gdy któryś zacznie nadawać, dopisuje
 *  wydarzenie do kalendarza. Kolumna „ostatnie sprawdzenie" pochodzi z
 *  `monitor.channel_checks` — jeśli świeci błędem, kanał zmienił nazwę albo
 *  YouTube odmówił odpowiedzi.
 */
import React, { useState } from "react";
import { Platform, StyleSheet, Switch, Text, TextInput, View } from "react-native";
import { liveAddChannel, liveUpdateChannel, LiveState } from "../../../api";
import { C, T } from "../../../theme";
import { Card, FadeIn, MetalButton, Press } from "../../../ui";

import Icon from "../../../ui/Icon";
const CATEGORIES = ["trump", "fed", "fda", "earnings", "macro", "manual"];
const CAT_LABEL: Record<string, string> = {
  trump: "TRUMP", fed: "FED", fda: "FDA", earnings: "WYNIKI", macro: "MAKRO", manual: "WŁASNE",
};

export default function ChannelsTab({
  st, busy, act,
}: {
  st: LiveState; busy: string;
  act: (label: string, fn: () => Promise<any>) => Promise<any>;
}) {
  const [adding, setAdding] = useState(false);
  const [form, setForm] = useState({ name: "", handle: "", category: "manual", lang: "en" });
  const [editId, setEditId] = useState<string | null>(null);
  const [draft, setDraft] = useState({ name: "", handle: "" });

  const channels = st.channels || [];
  const checks = st.monitor?.channel_checks || {};

  const submit = () => {
    if (!form.handle.trim()) return;
    act("addch", () => liveAddChannel({
      name: form.name.trim() || form.handle.trim(),
      handle: form.handle.trim(), category: form.category, lang: form.lang, watch: true,
    })).then(() => {
      setForm({ name: "", handle: "", category: "manual", lang: "en" });
      setAdding(false);
    });
  };

  return (
    <View>
      <Text style={s.intro}>
        Bot cyklicznie sprawdza te kanały. Gdy któryś wejdzie na żywo, wydarzenie samo
        pojawia się w kalendarzu — a jeśli jest śledzone, nasłuch startuje bez Ciebie.
      </Text>

      <MetalButton size="sm" label={adding ? "Anuluj" : "+ Dodaj kanał"}
                   onPress={() => setAdding((v) => !v)} />

      {adding && (
        <FadeIn>
          <Card style={s.form}>
            <TextInput style={s.input} placeholder="Nazwa, np. Bloomberg TV"
                       placeholderTextColor={C.dim} value={form.name}
                       onChangeText={(v) => setForm({ ...form, name: v })} />
            <TextInput style={s.input} placeholder="@handle z YouTube" autoCapitalize="none"
                       placeholderTextColor={C.dim} value={form.handle}
                       onChangeText={(v) => setForm({ ...form, handle: v })} />
            <View style={s.chips}>
              {CATEGORIES.map((k) => (
                <Press key={k} onPress={() => setForm({ ...form, category: k })}
                       style={[s.chip, form.category === k && s.chipOn]}>
                  <Text style={[s.chipTxt, form.category === k && { color: C.green }]}>
                    {CAT_LABEL[k]}
                  </Text>
                </Press>
              ))}
              {["en", "pl"].map((l) => (
                <Press key={l} onPress={() => setForm({ ...form, lang: l })}
                       style={[s.chip, form.lang === l && s.chipOn]}>
                  <Text style={[s.chipTxt, form.lang === l && { color: C.green }]}>
                    {l.toUpperCase()}
                  </Text>
                </Press>
              ))}
            </View>
            <MetalButton size="sm" tone="green"
                         label={busy === "addch" ? "Dodaję…" : "Dodaj"} onPress={submit} />
          </Card>
        </FadeIn>
      )}

      <Text style={s.count}>{channels.length} {channels.length === 1 ? "kanał" : "kanałów"}</Text>

      {channels.map((ch: any, i: number) => {
        const chk = checks[ch.id] || {};
        const editing = editId === ch.id;
        return (
          <FadeIn key={ch.id} delay={Math.min(i * 22, 200)} offset={8}>
            <Card style={s.row}>
              <View style={s.rowTop}>
                <Switch value={Boolean(ch.watch)}
                        onValueChange={(v) => act(ch.id, () => liveUpdateChannel(ch.id, { watch: v }))}
                        trackColor={{ false: "#2a3247", true: "rgba(47,212,138,.5)" }}
                        thumbColor={ch.watch ? C.green : "#fff"} />
                <View style={{ flex: 1, marginLeft: 4 }}>
                  <View style={s.nameRow}>
                    <Text style={s.name} numberOfLines={1}>{ch.name}</Text>
                    {chk.live && (
                      <View style={s.liveTag}>
                        <View style={s.liveDot} />
                        <Text style={s.liveTxt}>NA ŻYWO</Text>
                      </View>
                    )}
                  </View>
                  <Text style={s.handle} numberOfLines={1}>
                    {ch.handle}
                    {ch.category ? `  ·  ${CAT_LABEL[ch.category] || ch.category}` : ""}
                    {ch.lang ? `  ·  ${String(ch.lang).toUpperCase()}` : ""}
                  </Text>
                  {!!chk.error && <View style={s.errRow}>
                      <Icon name="uwaga" size={11} color={C.amber} />
                      <Text style={s.err} numberOfLines={2}>{chk.error}</Text>
                    </View>}
                </View>
                <Press style={s.iconBtn}
                       onPress={() => {
                         setEditId(editing ? null : ch.id);
                         setDraft({ name: ch.name || "", handle: ch.handle || "" });
                       }}>
                  <Icon name="recznie" size={14} color={C.muted} />
                </Press>
                <Press style={s.iconBtn}
                       onPress={() => act(ch.id, () => liveUpdateChannel(ch.id, { delete: true }))}>
                  <Icon name="kosz" size={14} color={C.muted} />
                </Press>
              </View>

              {editing && (
                <View style={s.editBox}>
                  <TextInput style={s.input} value={draft.name} placeholder="Nazwa"
                             placeholderTextColor={C.dim}
                             onChangeText={(v) => setDraft({ ...draft, name: v })} />
                  <TextInput style={s.input} value={draft.handle} placeholder="@handle"
                             autoCapitalize="none" placeholderTextColor={C.dim}
                             onChangeText={(v) => setDraft({ ...draft, handle: v })} />
                  <MetalButton size="sm" tone="green" label="Zapisz"
                               onPress={() => act(ch.id, () =>
                                 liveUpdateChannel(ch.id, { name: draft.name, handle: draft.handle }))
                                 .then(() => setEditId(null))} />
                </View>
              )}
            </Card>
          </FadeIn>
        );
      })}
    </View>
  );
}

const s = StyleSheet.create({
  intro: { color: C.muted, fontSize: 12.5, lineHeight: 18.5, marginBottom: 12 },
  form: { padding: 14, marginTop: 10, gap: 10 },
  input: {
    backgroundColor: C.elev, borderWidth: 1, borderColor: C.border2, borderRadius: 11,
    color: C.text, fontSize: 13, paddingHorizontal: 12,
    paddingVertical: Platform.OS === "ios" ? 11 : 8,
  },
  chips: { flexDirection: "row", flexWrap: "wrap", gap: 7 },
  chip: { paddingHorizontal: 10, paddingVertical: 6, borderRadius: 9, borderWidth: 1, borderColor: C.border2 },
  chipOn: { borderColor: C.green, backgroundColor: "rgba(47,212,138,.13)" },
  chipTxt: { color: C.muted, fontSize: 10.5, fontWeight: "700" },

  count: { color: C.dim, fontSize: 11, marginTop: 16, marginBottom: 8 },
  row: { padding: 12, marginBottom: 8 },
  rowTop: { flexDirection: "row", alignItems: "center", gap: 6 },
  nameRow: { flexDirection: "row", alignItems: "center", gap: 7 },
  name: { color: C.text, fontSize: 13.5, fontWeight: "700", flexShrink: 1 },
  handle: { color: C.dim, fontSize: 11, marginTop: 2 },
  errRow: { flexDirection: "row", alignItems: "flex-start", gap: 5, marginTop: 3 },
  err: { flex: 1, color: C.amber, fontSize: 10.5, lineHeight: 14.5 },
  liveTag: {
    flexDirection: "row", alignItems: "center", gap: 4,
    backgroundColor: "rgba(255,92,108,.16)", paddingHorizontal: 6, paddingVertical: 2,
    borderRadius: 5,
  },
  liveDot: { width: 5, height: 5, borderRadius: 3, backgroundColor: C.red },
  liveTxt: { color: C.red, fontSize: 9, fontWeight: "800" },

  iconBtn: {
    width: 32, height: 30, borderRadius: 9, borderWidth: 1, borderColor: C.border2,
    alignItems: "center", justifyContent: "center",
  },
  iconTxt: { color: C.muted, fontSize: 12.5 },
  editBox: { gap: 9, marginTop: 11 },
});
